#!/usr/bin/env python3
"""Independent reimplementation of the samtools command line suite.

Written from scratch in Python from observed behaviour of the reference
executable and the bundled examples / documentation.  It implements a
SAM/BAM reader & writer (including BGZF), BAM indexing, and the many
samtools subcommands on top of a common alignment-record model.
"""
import sys, os, re, io, gzip, zlib, struct, math, json, hashlib, binascii
import random, subprocess, tempfile, glob
from collections import defaultdict, Counter, OrderedDict
from copy import deepcopy

try:
    from help_data import HELP_DATA
except Exception:
    HELP_DATA = {}

VERSION = "5855b7e"
HTSLIB_VERSION = "1.23.1"

# ---------------------------------------------------------------- utilities

class SamtoolsError(Exception):
    def __init__(self, msg="", code=1, out=""):
        super().__init__(msg)
        self.msg = msg
        self.code = code
        self.out = out

class HelpExit(Exception):
    def __init__(self, out="", err="", code=0):
        self.out = out; self.err = err; self.code = code

def eprint(s=""):
    sys.stderr.write(s if (s.endswith("\n") or s == "") else s + "\n")

def _write_out(text, path=None, binary=False):
    if path and path != "-":
        mode = "wb" if binary else "w"
        with open(path, mode) as fh:
            fh.write(text)
    else:
        if binary:
            sys.stdout.buffer.write(text)
        else:
            sys.stdout.write(text)

def captured(cmd, key):
    try:
        return HELP_DATA[cmd][key]
    except Exception:
        return None

def raise_captured(cmd, key):
    d = captured(cmd, key)
    if d:
        raise HelpExit(d.get("out",""), d.get("err",""), d.get("exit",1))
    raise HelpExit("", "", 1)

def usage_error(cmd, first_line):
    """Raise HelpExit with the captured usage body for cmd and a custom
    getopt-style first line."""
    d = captured(cmd, "badshort") or captured(cmd, "badlong") or captured(cmd, "--help")
    body = ""
    exitcode = 1
    if d:
        txt = d.get("err") or d.get("out") or ""
        lines = txt.split("\n", 1)
        body = lines[1] if len(lines) > 1 else ""
        exitcode = d.get("exit", 1)
        # stats/coverage/samples print usage to stdout even for errors
        if d.get("out") and not d.get("err"):
            # For these, captured badshort err is just the getopt line
            pass
    raise HelpExit("", first_line + "\n" + body, exitcode)

def usage_noargs(cmd):
    d = captured(cmd, "noargs")
    if d:
        raise HelpExit(d.get("out",""), d.get("err",""), d.get("exit",1))
    raise HelpExit("", "", 1)

# Flag definitions ------------------------------------------------------
FLAG_DEFS = [
    (0x1, "PAIRED", "paired-end / multiple-segment sequencing technology"),
    (0x2, "PROPER_PAIR", "each segment properly aligned according to aligner"),
    (0x4, "UNMAP", "segment unmapped"),
    (0x8, "MUNMAP", "next segment in the template unmapped"),
    (0x10, "REVERSE", "SEQ is reverse complemented"),
    (0x20, "MREVERSE", "SEQ of next segment in template is rev.complemented"),
    (0x40, "READ1", "the first segment in the template"),
    (0x80, "READ2", "the last segment in the template"),
    (0x100, "SECONDARY", "secondary alignment"),
    (0x200, "QCFAIL", "not passing quality controls or other filters"),
    (0x400, "DUP", "PCR or optical duplicate"),
    (0x800, "SUPPLEMENTARY", "supplementary alignment"),
]
FLAG_BY_NAME = {n: v for v, n, _ in FLAG_DEFS}
# aliases accepted by htslib flag parsing (lowercase names in filters etc.)
FLAG_ALIASES = {
    "PAIR": 0x1, "PAIRED": 0x1, "PROPER": 0x2, "PROPER_PAIR": 0x2, "PROPERPAIR": 0x2,
    "UNMAPPED": 0x4, "UNMAP": 0x4, "MUNMAPPED": 0x8, "MUNMAP": 0x8,
    "REVERSE": 0x10, "REVERSED": 0x10, "MREVERSE": 0x20, "MREVERSED": 0x20,
    "READ1": 0x40, "READ2": 0x80, "SECONDARY": 0x100, "QCFAIL": 0x200,
    "DUP": 0x400, "DUPLICATE": 0x400, "SUPPLEMENTARY": 0x800, "SUPPLEMENT": 0x800,
    "PRIMARY": 0,  # not a bit; handled specially elsewhere if needed
}

def parse_flag_value(s):
    """Parse a flag specification: int (dec/hex/oct) or comma names."""
    if isinstance(s, int):
        return s
    s = str(s).strip()
    if s == "":
        return 0
    # hex / oct / dec
    try:
        if re.fullmatch(r"[+-]?0[xX][0-9a-fA-F]+", s):
            return int(s, 16)
        if re.fullmatch(r"[+-]?0[0-7]+", s) and len(s) > 1:
            return int(s, 8)
        if re.fullmatch(r"[+-]?\d+", s):
            return int(s, 10)
    except ValueError:
        pass
    val = 0
    for part in s.split(","):
        p = part.strip()
        neg = False
        if p.startswith("~") or p.startswith("!"):
            neg = True; p = p[1:]
        key = p.upper()
        if key in FLAG_BY_NAME:
            v = FLAG_BY_NAME[key]
        elif key in FLAG_ALIASES and key != "PRIMARY":
            v = FLAG_ALIASES[key]
        else:
            raise SamtoolsError(f"Could not parse flag: {s}")
        if neg:
            val &= ~v
        else:
            val |= v
    return val

def parse_int(s):
    s = str(s).strip()
    mult = 1
    if s and s[-1] in "kKmMgG":
        mult = {"k":1000,"K":1000,"m":1000000,"M":1000000,"g":1000000000,"G":1000000000}[s[-1]]
        s = s[:-1]
    try:
        return int(float(s) * mult)
    except ValueError:
        try:
            return int(s, 0)
        except Exception:
            raise SamtoolsError(f"invalid integer: {s}")

# argument parsing ------------------------------------------------------
class OptParser:
    """Minimal GNU-getopt-long-like parser.

    spec: dict canonical_name -> dict(short='o', long=['output'], arg=True/False)
    We store values keyed by canonical name (or short char if no name given).
    Repeatable options accumulate into a list when 'multi' set.
    """
    def __init__(self, cmd, spec):
        self.cmd = cmd
        self.spec = spec  # list of dicts
        self.by_short = {}
        self.by_long = {}
        for ent in spec:
            if ent.get("short"):
                self.by_short[ent["short"]] = ent
            for lg in ent.get("long") or []:
                self.by_long[lg] = ent
        self.values = {}
        self.positionals = []

    def _set(self, ent, val):
        key = ent["name"]
        if ent.get("multi"):
            self.values.setdefault(key, []).append(val)
        else:
            self.values[key] = val

    def _err_prefix(self):
        # most commands use "<cmd>: ..." ; view uses "samtools view: ..."
        if self.cmd == "view":
            return "samtools view"
        return self.cmd

    def unrecognised_long(self, name):
        word = "unrecognised" if self.cmd == "view" else "unrecognized"
        usage_error(self.cmd, f"{self._err_prefix()}: {word} option '--{name}'")

    def invalid_short(self, ch):
        usage_error(self.cmd, f"{self._err_prefix()}: invalid option -- '{ch}'")

    def missing_arg_short(self, ch):
        usage_error(self.cmd, f"{self._err_prefix()}: option requires an argument -- '{ch}'")

    def missing_arg_long(self, name):
        usage_error(self.cmd, f"{self._err_prefix()}: option '--{name}' requires an argument")

    def parse(self, args):
        i = 0
        end_opts = False
        while i < len(args):
            a = args[i]
            if end_opts or a == "-" or not a.startswith("-") or a == "":
                self.positionals.append(a); i += 1; continue
            if a == "--":
                end_opts = True; i += 1; continue
            if a.startswith("--"):
                body = a[2:]
                if "=" in body:
                    name, val = body.split("=", 1); has_val = True
                else:
                    name, val, has_val = body, None, False
                ent = self.by_long.get(name)
                if ent is None:
                    # unique prefix match (GNU abbreviation)
                    cands = [k for k in self.by_long if k.startswith(name)]
                    uniq = {id(self.by_long[k]) for k in cands}
                    if len(uniq) == 1 and cands:
                        ent = self.by_long[cands[0]]
                    else:
                        self.unrecognised_long(name)
                if ent.get("help"):
                    # raise captured help for exact token used
                    key = "--help" if name in ("help",) else None
                    ent_help = ent.get("help")
                    if isinstance(ent_help, str):
                        raise_captured(self.cmd, ent_help)
                    raise_captured(self.cmd, "--help")
                if ent.get("arg"):
                    if not has_val:
                        i += 1
                        if i >= len(args):
                            self.missing_arg_long(name)
                        val = args[i]
                    self._set(ent, val)
                elif ent.get("optarg"):
                    self._set(ent, val if has_val else True)
                else:
                    if has_val:
                        # getopt would complain; treat as unrecognised-ish
                        self._set(ent, True)
                    else:
                        # counting flags (e.g. -a -a)
                        if ent.get("count"):
                            self.values[ent["name"]] = self.values.get(ent["name"], 0) + 1
                        else:
                            self._set(ent, True)
                i += 1; continue
            # short cluster
            cluster = a[1:]
            j = 0
            consumed_next = False
            while j < len(cluster):
                ch = cluster[j]
                ent = self.by_short.get(ch)
                if ent is None:
                    self.invalid_short(ch)
                if ent.get("help"):
                    if isinstance(ent.get("help"), str):
                        raise_captured(self.cmd, ent["help"])
                    raise_captured(self.cmd, "-h")
                if ent.get("arg"):
                    rest = cluster[j+1:]
                    if rest:
                        # -oFILE or -o=FILE
                        if rest.startswith("="):
                            rest = rest[1:]
                        self._set(ent, rest)
                    else:
                        i += 1
                        if i >= len(args):
                            self.missing_arg_short(ch)
                        self._set(ent, args[i]); consumed_next = True
                    j = len(cluster); break
                elif ent.get("optarg"):
                    rest = cluster[j+1:]
                    self._set(ent, rest if rest else True)
                    j = len(cluster); break
                else:
                    if ent.get("count"):
                        self.values[ent["name"]] = self.values.get(ent["name"], 0) + 1
                    else:
                        self._set(ent, True)
                    j += 1
            i += 1
        return self.values, self.positionals

def S(name, short=None, long=None, arg=False, multi=False, count=False, help=False, optarg=False):
    if isinstance(long, str): long = [long]
    return {"name": name, "short": short, "long": long or [], "arg": arg,
            "multi": multi, "count": count, "help": help, "optarg": optarg}

def global_opts(name_prefix=""):
    return [
        S("input_fmt_option", long="input-fmt-option", arg=True, multi=True),
        S("output_fmt", short="O", long="output-fmt", arg=True),
        S("output_fmt_option", long="output-fmt-option", arg=True, multi=True),
        S("reference", short="T", long="reference", arg=True),
        S("threads", short="@", long="threads", arg=True),
        S("write_index", long="write-index"),
        S("verbosity", long="verbosity", arg=True),
        S("no_PG", long="no-PG"),
    ]

def get_opt(vals, name, default=None):
    return vals.get(name, default)

