# ---------------------------------------------------------------- header
def parse_header_line(line):
    fields = line.split("\t")
    typ = fields[0]
    tags = OrderedDict()
    rest = []
    for f in fields[1:]:
        if len(f) >= 3 and f[2] == ":":
            tags[f[:2]] = f[3:]
        else:
            rest.append(f)
    return typ, tags, rest

