        if self._refs_override is not None:
            return list(self._refs_override)
        out = []
        for ln in self.lines:
            if ln.startswith("@SQ"):
                _, tags, _ = parse_header_line(ln)
                if "SN" in tags:
                    try: ln_len = int(tags.get("LN", "0"))
                    except Exception: ln_len = 0
                    out.append((tags["SN"], ln_len))
        return out
