        """Add an @PG line replicating htslib sam_hdr_add_pg behaviour."""
        pg_ids = []
        for ln in self.lines:
            if ln.startswith("@PG"):
                _, tags, _ = parse_header_line(ln)
                if "ID" in tags:
                    pg_ids.append(tags["ID"])
