        self.rnext = rnext; self.pnext = int(pnext); self.tlen = int(tlen)
        self.seq = seq; self.qual = qual
        self.tags = list(tags) if tags else []
        self._voffset = 0; self._end_voffset = 0
    def copy(self):
        r = Record(self.qname, self.flag, self.rname, self.pos, self.mapq,
                   list(self.cigar), self.rnext, self.pnext, self.tlen,
                   self.seq, self.qual, deepcopy(self.tags))
        r._voffset = self._voffset; r._end_voffset = self._end_voffset
        return r
    # flags helpers
    def is_unmapped(self): return bool(self.flag & 0x4)
    def is_reverse(self): return bool(self.flag & 0x10)
    def is_secondary(self): return bool(self.flag & 0x100)
    def is_supplementary(self): return bool(self.flag & 0x800)
    def is_qcfail(self): return bool(self.flag & 0x200)
    def is_duplicate(self): return bool(self.flag & 0x400)
    def is_paired(self): return bool(self.flag & 0x1)
    # tags
    def get_tag(self, name, default=None):
        for t, ty, v in self.tags:
            if t == name:
                return v
        return default
    def get_tag_typed(self, name):
        for t, ty, v in self.tags:
            if t == name:
                return (ty, v)
        return None
    def has_tag(self, name):
        return any(t == name for t, _, _ in self.tags)
    def set_tag(self, name, typ, value):
        for i, (t, ty, v) in enumerate(self.tags):
            if t == name:
                self.tags[i] = (name, typ, value); return
        self.tags.append((name, typ, value))
    def del_tag(self, name):
        self.tags = [tg for tg in self.tags if tg[0] != name]
