    def ref_span(self):
        return sum(n for n, op in self.cigar if op in CIGAR_REF_CONSUME)
    def end_pos(self):
        """1-based inclusive end, htslib bam_endpos (pos 0-based + span)."""
        if self.pos <= 0:
            return 0
        span = self.ref_span()
        return self.pos + span - 1 if span > 0 else self.pos
    def end_pos_excl(self):
        # bam_endpos returns 0-based exclusive == pos1-1 + span
        if self.pos <= 0: return 0
        return self.pos - 1 + max(self.ref_span(), 0) if self.cigar else self.pos - 1
    def query_len_cigar(self):
        return sum(n for n, op in self.cigar if op in CIGAR_QUERY_CONSUME)
    def seq_len(self):
        return 0 if self.seq == "*" else len(self.seq)
    def qual_list(self):
        if self.qual == "*" or self.qual == "":
            return [255] * self.seq_len()
        return [ord(c) - 33 for c in self.qual]
    def aligned_pairs(self):
        """Yield (qpos0 or None, refpos1 or None, op)."""
        q = 0; r = self.pos
        if self.pos <= 0:
            return
        for n, op in self.cigar:
            if op in "M=X":
                for _ in range(n):
                    yield (q, r, op); q += 1; r += 1
            elif op == "I" or op == "S":
                for _ in range(n):
                    yield (q, None, op); q += 1
            elif op in "DN":
                for _ in range(n):
                    yield (None, r, op); r += 1
            elif op == "H":
                pass
            elif op == "P":
                for _ in range(n):
                    yield (None, r, op); r += 1
            elif op == "B":
                # backward: move ref/query back (rare)
                q -= n; r -= n
                if q < 0: q = 0
                if r < self.pos: r = self.pos
    def to_sam(self, header=None):
        seq = self.seq if self.seq else "*"
        qual = self.qual if self.qual else "*"
        fields = [self.qname, str(self.flag), self.rname, str(self.pos),
                  str(self.mapq), cigar_to_str(self.cigar), self.rnext,
                  str(self.pnext), str(self.tlen), seq, qual]
        for name, typ, v in self.tags:
            fields.append(format_tag_sam(name, typ, v))
        return "\t".join(fields)

def format_tag_sam(name, typ, v):
    if typ == "B":
        subtype, vals = v
        if subtype == "f" or subtype == "d":
            body = ",".join(format_float_sam(x) for x in vals)
        else:
            body = ",".join(str(int(x)) for x in vals)
        return f"{name}:B:{subtype},{body}" if vals else f"{name}:B:{subtype}"
    if typ in ("i","c","C","s","S","I"):
        return f"{name}:i:{int(v)}"
    if typ == "f" or typ == "d":
        return f"{name}:f:{format_float_sam(v)}"
    if typ == "A":
        return f"{name}:A:{v}"
    if typ == "H":
        # v may be bytes or str
        if isinstance(v, (bytes, bytearray)):
            return f"{name}:H:{bytes(v).hex()}"
        return f"{name}:H:{v}"
    return f"{name}:Z:{v}"

def format_float_sam(v):
    # htslib prints floats via "%g" -like shortest? Use repr trimmed.
    try:
        fv = float(v)
    except Exception:
        return str(v)
    # Preserve C-like output for common values
    s = ("%.6g" % fv)
    return s

def parse_tag_sam(field):
    # TAG:TYPE:VALUE (VALUE may contain colons)
    if len(field) < 5 or field[2] != ":" or field[4] != ":":
        return None
    name = field[:2]; typ = field[3]; val = field[5:]
    if typ == "i":
        try: return (name, "i", int(val))
        except Exception:
            try: return (name, "i", int(float(val)))
            except Exception: return (name, "i", 0)
    if typ == "f" or typ == "d":
        try: return (name, "f", float(val))
        except Exception: return (name, "f", 0.0)
    if typ == "A":
        return (name, "A", val[:1] if val else " ")
    if typ == "Z" or typ == "H":
        return (name, typ, val)
    if typ == "B":
        parts = val.split(",")
        subtype = parts[0] if parts and parts[0] else "i"
        vals = []
        for x in parts[1:]:
            if subtype in "fd":
                vals.append(float(x))
            else:
                vals.append(int(x))
        return (name, "B", (subtype, vals))
    return (name, typ, val)

def record_from_sam_line(line):
    f = line.rstrip("\n").rstrip("\r").split("\t")
    if len(f) < 11:
        # tolerate space? htslib requires TAB
        raise SamtoolsError("truncated SAM record")
    tags = []
    for fld in f[11:]:
        tg = parse_tag_sam(fld)
        if tg: tags.append(tg)
    seq = f[9].upper() if f[9] != "*" else "*"
    r = Record(qname=f[0], flag=int(f[1]) if f[1].lstrip("-").isdigit() else parse_flag_value(f[1]),
               rname=f[2], pos=int(f[3]), mapq=int(f[4]), cigar=parse_cigar(f[5]),
               rnext=f[6], pnext=int(f[7]), tlen=int(f[8]), seq=seq, qual=f[10], tags=tags)
    return r

