class BGZFWriter:
    def __init__(self, fh, level=6):
        self.fh = fh
        self.level = level
        self.buf = bytearray()
        self.block_addr = 0
    def write(self, data):
        self.buf += data
        while len(self.buf) >= 65000:
            self._flush_block(bytes(self.buf[:65000]))
            del self.buf[:65000]
    def _flush_block(self, chunk):
        if not chunk:
            return
        comp = zlib.compressobj(self.level, zlib.DEFLATED, -15)
        cdata = comp.compress(chunk) + comp.flush()
        bsize = 18 + len(cdata) + 8 - 1
