        # Build explicitly: ID1 ID2 CM FLG MTIME(4) XFL OS XLEN(2) then BC subfield
        header = b"\x1f\x8b\x08\x04\x00\x00\x00\x00\x00\xff\x06\x00" + b"BC" + struct.pack("<HH", 2, bsize)
        crc = binascii.crc32(chunk) & 0xffffffff
        trailer = struct.pack("<II", crc, len(chunk) & 0xffffffff)
        block = header + cdata + trailer
        self.fh.write(block)
        self.block_addr += len(block)
    def tell_voffset(self):
        return (self.block_addr << 16) | len(self.buf)
    def close(self):
