class BGZFBlocks:
    """Decompress a BGZF/gzip byte string, tracking block offsets.
    Returns (data, block_map) where block_map is list of
    (compressed_addr, uncompressed_start, uncompressed_len)."""
    @staticmethod
    def decompress(data):
        out = bytearray(); blocks = []
        off = 0; n = len(data)
        while off < n:
            if n - off < 18:
                break
            if data[off] != 0x1f or data[off+1] != 0x8b:
                break
            flg = data[off+3]
            xlen = struct.unpack_from("<H", data, off+10)[0] if flg & 4 else 0
            bsize = None
            p = off + 12; endx = p + xlen
            while p + 4 <= endx:
                si = data[p:p+2]; slen = struct.unpack_from("<H", data, p+2)[0]
                if si == b"BC" and slen == 2:
                    bsize = struct.unpack_from("<H", data, p+4)[0] + 1
                p += 4 + slen
            start_uncomp = len(out)
            comp_start = off
            if bsize is not None:
                block = data[off:off+bsize]
                try:
                    chunk = gzip.decompress(block)
                except Exception:
                    # BGZF header is 18 bytes typically; trailer 8
                    hdr_len = 12 + xlen
                    chunk = zlib.decompress(block[hdr_len:-8], -15)
                out += chunk
                blocks.append((comp_start, start_uncomp, len(chunk)))
                off += bsize
            else:
                # plain gzip member: use gzip stream from here
                try:
                    d = zlib.decompressobj(31)
                    chunk = d.decompress(data[off:])
                    consumed = n - off - len(d.unused_data)
                    out += chunk
                    blocks.append((comp_start, start_uncomp, len(chunk)))
                    off += consumed if consumed > 0 else n
                except Exception:
                    break
            # stop at EOF block (empty chunk) if remaining looks empty? continue anyway
        return bytes(out), blocks
    @staticmethod
    def voffset(blocks, uncomp_pos):
        # binary-ish linear search (blocks are few for our test sizes)
        cur = (0, 0, 0)
        for b in blocks:
            if b[1] <= uncomp_pos:
                cur = b
            else:
                break
        return (cur[0] << 16) | (uncomp_pos - cur[1])

def reg2bin(beg, end):
    end -= 1
    if beg >> 14 == end >> 14: return 4681 + (beg >> 14)
    if beg >> 17 == end >> 17: return 585 + (beg >> 17)
    if beg >> 20 == end >> 20: return 73 + (beg >> 20)
    if beg >> 23 == end >> 23: return 9 + (beg >> 23)
    if beg >> 26 == end >> 26: return 1 + (beg >> 26)
    return 0

def _smallest_int_type(v):
    if -128 <= v <= 127: return "c"
    if 0 <= v <= 255: return "C"
    if -32768 <= v <= 32767: return "s"
    if 0 <= v <= 65535: return "S"
    if -2147483648 <= v <= 2147483647: return "i"
    return "I"

_INT_FMT = {"c": "<b", "C": "<B", "s": "<h", "S": "<H", "i": "<i", "I": "<I"}

def encode_bam_record(rec, ref_index):
    refID = ref_index.get(rec.rname, -1) if rec.rname not in ("*", "") else -1
    if rec.rname in ("*", ""): refID = -1
    pos0 = rec.pos - 1 if rec.pos > 0 else -1
    if refID < 0:
        pos0 = -1 if rec.pos <= 0 else rec.pos - 1
        if rec.rname in ("*", ""):
            pos0 = -1
    # next ref
    if rec.rnext == "=":
        next_refID = refID
    elif rec.rnext in ("*", ""):
        next_refID = -1
    else:
        next_refID = ref_index.get(rec.rnext, -1)
    next_pos0 = rec.pnext - 1 if rec.pnext > 0 else -1
    if next_refID < 0: next_pos0 = -1
    qname_b = rec.qname.encode() + b"\x00"
    l_seq = 0 if rec.seq == "*" else len(rec.seq)
    cigar_words = []
    cigar = rec.cigar
    extra_tags = list(rec.tags)
    # Long CIGAR handling via CG tag (B: I?? actually 'CG' with B:I in spec conventions)
    use_cg = False
    if len(cigar) > 65535:
        use_cg = True
    for ln, op in cigar:
        opi = CIGAR_OPS.index(op)
        cigar_words.append((ln << 4) | opi)
    n_cigar = len(cigar_words)
    if use_cg:
        extra_tags = [("CG", "B", ("I", cigar_words))] + extra_tags
        cigar_words = cigar_words[:2]  # placeholder (rare)
        n_cigar = len(cigar_words)
    # bin
    if refID >= 0 and pos0 >= 0:
        end0 = pos0 + rec.ref_span()
        binv = reg2bin(pos0, end0 if end0 > pos0 else pos0 + 1)
    else:
        # htslib: unmapped placed reads use bin of pos? unplaced 0/4680
        binv = reg2bin(pos0, pos0 + 1) if pos0 >= 0 else 0
    seq_b = bytearray()
    if rec.seq != "*":
        s = rec.seq.upper()
        for i in range(0, len(s), 2):
            hi = _SEQ_ENC.get(s[i], 15)
            lo = _SEQ_ENC.get(s[i+1], 15) if i + 1 < len(s) else 0
            seq_b.append((hi << 4) | lo)
