        qual_b = bytes([0xff]) * l_seq
    else:
        qual_b = bytes((ord(c) - 33) & 0xff for c in rec.qual[:l_seq])
        if len(qual_b) < l_seq:
            qual_b += bytes([0xff]) * (l_seq - len(qual_b))
