        l_name = struct.unpack_from("<i", data, off)[0]; off += 4
        name = data[off:off+l_name].rstrip(b"\x00").decode(); off += l_name
        l_ref = struct.unpack_from("<i", data, off)[0]; off += 4
        refs.append((name, l_ref))
