    records = []
    while off < len(data):
        start = off
        if off + 4 > len(data): break
        block_size = struct.unpack_from("<i", data, off)[0]; off += 4
        if block_size < 32: break
        rec_start = off
        refID, pos0, l_read_name, mapq, binv, n_cigar, flag, l_seq, next_refID, next_pos0, tlen = \
            struct.unpack_from("<iiBBHHHiii", data, off); off += 32
        qname = data[off:off+l_read_name].rstrip(b"\x00").decode(errors="replace"); off += l_read_name
        cigar = []
        for _ in range(n_cigar):
            w = struct.unpack_from("<I", data, off)[0]; off += 4
            cigar.append((w >> 4, CIGAR_OPS[w & 0xf] if (w & 0xf) < len(CIGAR_OPS) else "M"))
        seq_chars = []
        n_seqb = (l_seq + 1) // 2
        for i in range(l_seq):
            b = data[off + i // 2]
            nib = (b >> 4) if i % 2 == 0 else (b & 0xf)
            seq_chars.append(_SEQ_ENC_STR[nib])
        off += n_seqb
        qual_bytes = data[off:off+l_seq]; off += l_seq
        if l_seq == 0:
            seq = "*"; qual = "*"
        else:
            seq = "".join(seq_chars)
            if len(qual_bytes) == l_seq and all(b == 0xff for b in qual_bytes):
                qual = "*"
            else:
                qual = "".join(chr(b + 33) for b in qual_bytes)
        end_rec = rec_start + block_size
        tags = []
        cg_cigar = None
        while off < end_rec:
            if off + 3 > end_rec: break
            tname = data[off:off+2].decode(); ttype = chr(data[off+2]); off += 3
            if ttype == "A":
                v = chr(data[off]); off += 1; tags.append((tname, "A", v))
            elif ttype in _INT_FMT:
                fmt = _INT_FMT[ttype]; sz = struct.calcsize(fmt)
                v = struct.unpack_from(fmt, data, off)[0]; off += sz
                tags.append((tname, "i", v))
            elif ttype == "f":
                v = struct.unpack_from("<f", data, off)[0]; off += 4; tags.append((tname, "f", v))
            elif ttype == "d":
                v = struct.unpack_from("<d", data, off)[0]; off += 8; tags.append((tname, "f", v))
            elif ttype in ("Z", "H"):
                z = data.index(b"\x00", off)
                v = data[off:z].decode(errors="replace"); off = z + 1
                tags.append((tname, ttype, v))
            elif ttype == "B":
                subtype = chr(data[off]); off += 1
                cnt = struct.unpack_from("<i", data, off)[0]; off += 4
                vals = []
                for _ in range(cnt):
                    if subtype == "f":
                        vals.append(struct.unpack_from("<f", data, off)[0]); off += 4
                    elif subtype == "d":
                        vals.append(struct.unpack_from("<d", data, off)[0]); off += 8
                    elif subtype in _INT_FMT:
                        fmt = _INT_FMT[subtype]; sz = struct.calcsize(fmt)
                        vals.append(struct.unpack_from(fmt, data, off)[0]); off += sz
                    else:
                        break
                if tname == "CG" and n_cigar and cigar and (flag is not None):
                    cg_cigar = vals
                    # CG is retained in SAM output by htslib? It is hidden usually.
                    # Keep it out of tags; real cigar reconstructed below.
                else:
                    tags.append((tname, "B", (subtype, vals)))
            else:
                break
        off = end_rec
        if cg_cigar is not None:
            cigar = [((w >> 4), CIGAR_OPS[w & 0xf]) for w in cg_cigar]
        rname = refs[refID][0] if 0 <= refID < len(refs) else "*"
        if next_refID == refID and next_refID >= 0:
            rnext = "="
        elif 0 <= next_refID < len(refs):
            rnext = refs[next_refID][0]
        else:
            rnext = "*"
        rec = Record(qname=qname, flag=flag, rname=rname,
                     pos=(pos0 + 1 if pos0 >= 0 else 0), mapq=mapq, cigar=cigar,
                     rnext=rnext, pnext=(next_pos0 + 1 if next_pos0 >= 0 else 0),
                     tlen=tlen, seq=seq, qual=qual, tags=tags)
        if blocks:
            rec._voffset = BGZFBlocks.voffset(blocks, start)
            rec._end_voffset = BGZFBlocks.voffset(blocks, off)
        records.append(rec)
    return header, records

