def parse_region_str(s):
    """Parse 'chr', 'chr:start', 'chr:start-end', 'chr:-end', 'chr:start-'.
    Returns (chrom, start1 or None, end1 or None) with numbers allowing commas.
    If it looks like plain chrom with colons in name, fallback."""
    if s == "*":
        return ("*", None, None)
    # Find colon whose suffix matches position spec
    # Try last colon first
    for idx in [i for i, c in enumerate(s) if c == ":"][::-1]:
        suffix = s[idx+1:]
        if suffix == "":
            return (s[:idx], None, None)
        if re.fullmatch(r"[\d,]*-[\d,]*", suffix) or re.fullmatch(r"[\d,]+", suffix):
            chrom = s[:idx]
            if "-" in suffix:
                a, b = suffix.split("-", 1)
                start = int(a.replace(",", "")) if a else None
                end = int(b.replace(",", "")) if b else None
            else:
