def write_gzi(gz_path, gzi_path):
    # Build BGZF/gzip index: pairs of (compressed, uncompressed) offsets.
    # For plain gzip, htslib gzi uses bgzf blocks if present; otherwise
    # a single entry? Implement by scanning gzip members/BGZF blocks.
    try:
        data = open(gz_path, "rb").read()
    except Exception:
        return
    _, blocks = BGZFBlocks.decompress(data)
    pairs = []
    for comp, uncomp_start, _ in blocks:
        if comp != 0 or uncomp_start != 0:
            pairs.append((comp, uncomp_start))
    with open(gzi_path, "wb") as fh:
        fh.write(struct.pack("<Q", len(pairs)))
        for c, u in pairs:
            fh.write(struct.pack("<QQ", c, u))

def load_fai_file(fai_path):
    entries = OrderedDict()
    with open(fai_path) as fh:
        for ln in fh:
            if not ln.strip(): continue
            f = ln.rstrip("\n").split("\t")
            if len(f) >= 5:
                entries[f[0]] = (int(f[1]), int(f[2]), int(f[3]), int(f[4]),
                                 int(f[5]) if len(f) > 5 else None)
    return entries

def parse_region_str(s):
    """Parse 'chr', 'chr:start', 'chr:start-end', 'chr:-end', 'chr:start-'.
    Returns (chrom, start1 or None, end1 or None) with numbers allowing commas.
    If it looks like plain chrom with colons in name, fallback."""
    if s == "*":
        return ("*", None, None)
    # Find colon whose suffix matches position spec
    # Try last colon first
    for idx in [i for i, c in enumerate(s) if c == ":"][::-1]:
        suffix = s[idx+1:]
        if suffix == "":
            return (s[:idx], None, None)
        if re.fullmatch(r"[\d,]*-[\d,]*", suffix) or re.fullmatch(r"[\d,]+", suffix):
            chrom = s[:idx]
            if "-" in suffix:
                a, b = suffix.split("-", 1)
                start = int(a.replace(",", "")) if a else None
                end = int(b.replace(",", "")) if b else None
            else:
                start = int(suffix.replace(",", "")); end = None
            return (chrom, start, end)
    return (s, None, None)

def resolve_region(s, header):
    """Return (chrom, start1, end1_inclusive) or None if unknown chrom.
    start defaults 1, end defaults ref len (or large)."""
    chrom, start, end = parse_region_str(s)
    if chrom == "*":
        return ("*", 0, 0)
    refs = dict(header.refs) if header else {}
    if chrom not in refs:
        return None
    st = start if start is not None else 1
    if st < 1: st = 1 if start is not None and start >= 0 else st
    # Note: samtools region 'ref:0-10' is treated start 0->1? overlap logic uses 0-based interval [start-1..) hmm
    en = end if end is not None else refs[chrom]
    return (chrom, st, en)

def record_overlaps_region(rec, chrom, start1, end1):
    if chrom == "*":
        return rec.rname == "*" or rec.is_unmapped()
    if rec.rname != chrom:
        return False
    if rec.pos <= 0:
        return False
    rec_end = rec.end_pos()
    if rec_end < rec.pos: rec_end = rec.pos
    # region interval 1-based inclusive; if start1 may be 0 (from ref:0-10) treat as 1
    st = max(start1, 1)
    return not (rec_end < st or rec.pos > end1)

def read_bed(path):
    regions = []  # (chrom, start0, end0_exclusive, original_fields list, line)
    data = _read_file_bytes(path)
    dec, _ = open_maybe_gzip_bytes(data)
    text = dec.decode(errors="replace")
    for ln in text.splitlines():
        if not ln.strip() or ln.startswith("#") or ln.startswith("track") or ln.startswith("browser"):
            continue
        f = ln.split("\t")
        if len(f) < 3:
            f = ln.split()
        if len(f) < 3: continue
        # header line in some BED-like files
        try:
            st = int(f[1]); en = int(f[2])
        except Exception:
            continue
        regions.append((f[0], st, en, f, ln))
    return regions

