        return custom if os.path.exists(custom) else None
    if not bam_path or bam_path == "-":
        return None
    cands = []
    cands.append(bam_path + ".bai"); cands.append(bam_path + ".csi"); cands.append(bam_path + ".crai")
    base, ext = os.path.splitext(bam_path)
    if ext in (".bam",):
        cands.append(base + ".bai"); cands.append(base + ".csi")
    if ext in (".cram",):
        cands.append(base + ".crai")
    cands.append(bam_path + ".tbx")
    for c in cands:
        if os.path.exists(c):
            return c
    return None

def has_index(bam_path, custom=None):
    return find_index_path(bam_path, custom) is not None

