    dec, _ = open_maybe_gzip_bytes(data)
    text = dec.decode(errors="replace")
    out = []; name = None; desc = ""; seq_parts = []
    for ln in text.splitlines():
        if ln.startswith(">"):
            if name is not None:
                out.append((name, "".join(seq_parts), desc))
            header = ln[1:].strip()
            bits = header.split(None, 1)
            name = bits[0] if bits else ""
            desc = bits[1] if len(bits) > 1 else ""
            seq_parts = []
        else:
            if name is not None:
                seq_parts.append(ln.strip())
    if name is not None:
        out.append((name, "".join(seq_parts), desc))
    return out

def read_fastq(path):
    """Return list of (name_with_desc, seq, qual, name_only)."""
    data = _read_file_bytes(path)
    dec, _ = open_maybe_gzip_bytes(data)
    text = dec.decode(errors="replace")
    lines = text.splitlines()
    out = []; i = 0
    # Fast detection if FASTA instead
    if lines and lines[0].startswith(">"):
        for name, seq, desc in read_fasta_entries_from_text(text):
            full = name + ((" " + desc) if desc else "")
            out.append((full, seq, None, name))
        return out
    while i < len(lines):
        if lines[i].strip() == "":
            i += 1; continue
        if not lines[i].startswith("@"):
            i += 1; continue
        header = lines[i][1:]; i += 1
        seq_parts = []
        while i < len(lines) and not lines[i].startswith("+"):
            seq_parts.append(lines[i].strip()); i += 1
        if i < len(lines): i += 1  # '+' line
        seq = "".join(seq_parts)
        qual_parts = []
        qlen = 0
        while i < len(lines) and qlen < len(seq):
            qual_parts.append(lines[i]); qlen += len(lines[i]); i += 1
        qual = "".join(qual_parts)
        name_only = header.split()[0] if header.split() else header
        out.append((header, seq, qual, name_only))
    return out

