# ------------------------------------------------------------- filter expr
class FilterError(Exception):
    pass

_TOKEN_RE = re.compile(r"""\s*(?:(?P<tag>\[[A-Za-z][A-Za-z0-9]\])|
    (?P<num>0[xX][0-9a-fA-F]+|\d+\.\d*(?:[eE][+-]?\d+)?|\.\d+(?:[eE][+-]?\d+)?|\d+(?:[eE][+-]?\d+)?)|
    (?P<str>"(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*')|
    (?P<op>==|!=|<=|>=|=~|!~|&&|\|\||[+\-*/%<>&|^~!(),.])|
    (?P<ident>[A-Za-z_][A-Za-z0-9_]*))""", re.VERBOSE)

def _tokenize_expr(s):
    toks = []; i = 0
    while i < len(s):
        if s[i].isspace():
            i += 1; continue
        m = _TOKEN_RE.match(s, i)
        if not m or m.end() == i:
            raise FilterError(f"bad token at {s[i:]}")
        i = m.end()
        if m.group("tag") is not None:
            toks.append(("TAG", m.group("tag")[1:-1]))
        elif m.group("num") is not None:
            t = m.group("num")
            if t.lower().startswith("0x"):
                toks.append(("NUM", int(t, 16)))
            elif any(c in t for c in ".eE"):
                toks.append(("NUM", float(t)))
            else:
                toks.append(("NUM", int(t)))
        elif m.group("str") is not None:
            raw = m.group("str")[1:-1]
            try:
                import codecs
                val = codecs.decode(raw, "unicode_escape")
            except Exception:
                val = raw
            toks.append(("STR", val))
        elif m.group("op") is not None:
            toks.append(("OP", m.group("op")))
        elif m.group("ident") is not None:
            toks.append(("IDENT", m.group("ident")))
    toks.append(("EOF", None))
    return toks

class _ExprParser:
    def __init__(self, toks):
        self.toks = toks; self.i = 0
    def peek(self): return self.toks[self.i]
    def next(self):
        t = self.toks[self.i]; self.i += 1; return t
    def expect_op(self, op):
        t = self.next()
        if t != ("OP", op):
            raise FilterError(f"expected {op}")
    def parse(self):
        node = self.parse_or()
        if self.peek()[0] != "EOF":
            raise FilterError("trailing tokens")
        return node
    def parse_or(self):
        n = self.parse_and()
        while self.peek() == ("OP", "||") or self.peek() == ("IDENT","or"):
            self.next(); n = ("or", n, self.parse_and())
        return n
    def parse_and(self):
        n = self.parse_bitor()
        while self.peek() == ("OP", "&&") or self.peek() == ("IDENT","and"):
            self.next(); n = ("and", n, self.parse_bitor())
        return n
    def parse_bitor(self):
        n = self.parse_bitxor()
        while self.peek() == ("OP", "|"):
            self.next(); n = ("bin", "|", n, self.parse_bitxor())
        return n
    def parse_bitxor(self):
        n = self.parse_bitand()
        while self.peek() == ("OP", "^"):
            self.next(); n = ("bin", "^", n, self.parse_bitand())
        return n
    def parse_bitand(self):
        n = self.parse_cmp()
        while self.peek() == ("OP", "&"):
            self.next(); n = ("bin", "&", n, self.parse_cmp())
        return n
    def parse_cmp(self):
        n = self.parse_add()
        while self.peek()[0] == "OP" and self.peek()[1] in ("==","!=","<","<=",">",">=","=~","!~"):
            op = self.next()[1]; n = ("cmp", op, n, self.parse_add())
        return n
    def parse_add(self):
        n = self.parse_mul()
        while self.peek()[0] == "OP" and self.peek()[1] in ("+","-"):
            op = self.next()[1]; n = ("bin", op, n, self.parse_mul())
        return n
    def parse_mul(self):
        n = self.parse_unary()
        while self.peek()[0] == "OP" and self.peek()[1] in ("*","/","%"):
            op = self.next()[1]; n = ("bin", op, n, self.parse_unary())
        return n
    def parse_unary(self):
        if self.peek() == ("OP", "!"):
            self.next(); return ("not", self.parse_unary())
        if self.peek() == ("OP", "~"):
            self.next(); return ("bnot", self.parse_unary())
        if self.peek() == ("OP", "-"):
            self.next(); return ("neg", self.parse_unary())
        if self.peek() == ("OP", "+"):
            self.next(); return self.parse_unary()
        if self.peek() == ("IDENT", "not"):
            self.next(); return ("not", self.parse_unary())
        return self.parse_atom()
    def parse_atom(self):
        t = self.next()
        if t[0] == "NUM": return ("num", t[1])
        if t[0] == "STR": return ("str", t[1])
        if t[0] == "TAG": return ("tag", t[1])
        if t == ("OP", "("):
            n = self.parse_or(); self.expect_op(")"); return n
        if t[0] == "IDENT":
            name = t[1]
            # dotted flag.xxx or function call
            if self.peek() == ("OP", "("):
                self.next(); args = []
                if self.peek() != ("OP", ")"):
                    args.append(self.parse_or())
                    while self.peek() == ("OP", ","):
                        self.next(); args.append(self.parse_or())
                self.expect_op(")")
                return ("call", name, args)
            parts = [name]
            while self.peek() == ("OP", "."):
                self.next()
                t2 = self.next()
                if t2[0] != "IDENT":
                    raise FilterError("bad dotted name")
                parts.append(t2[1])
            return ("var", ".".join(parts))
        raise FilterError(f"unexpected token {t}")

