                return 1 if self._eval(a, rec, header) is not None else 0
            if fname == "abs":
                return abs(_to_num(self._eval(args[0], rec, header)))
            if fname in ("upper", "toupper"):
                v = self._eval(args[0], rec, header); return str(v).upper() if v is not None else ""
            if fname in ("lower", "tolower"):
                v = self._eval(args[0], rec, header); return str(v).lower() if v is not None else ""
            raise FilterError(f"unknown function {fname}")
        if kind == "not":
            return 0 if _truthy(self._eval(node[1], rec, header)) else 1
        if kind == "bnot":
            return ~int(_to_num(self._eval(node[1], rec, header)))
        if kind == "neg":
            return -_to_num(self._eval(node[1], rec, header))
        if kind == "and":
            return 1 if (_truthy(self._eval(node[1], rec, header)) and _truthy(self._eval(node[2], rec, header))) else 0
        if kind == "or":
            return 1 if (_truthy(self._eval(node[1], rec, header)) or _truthy(self._eval(node[2], rec, header))) else 0
        if kind == "bin":
            op = node[1]
            a = self._eval(node[2], rec, header); b = self._eval(node[3], rec, header)
            if op == "+" and (isinstance(a, str) or isinstance(b, str)):
                return ("" if a is None else str(a)) + ("" if b is None else str(b))
            an = _to_num(a); bn = _to_num(b)
            if op == "&": return int(an) & int(bn)
            if op == "|": return int(an) | int(bn)
            if op == "^": return int(an) ^ int(bn)
            if op == "+": return an + bn
            if op == "-": return an - bn
            if op == "*": return an * bn
            if op == "/": return (an / bn) if bn != 0 else 0
            if op == "%": return (an % bn) if bn != 0 else 0
        if kind == "cmp":
            op = node[1]
            a = self._eval(node[2], rec, header); b = self._eval(node[3], rec, header)
            if a is None or b is None:
                return 0
            if op in ("=~", "!~"):
                try:
                    m = re.search(str(b), str(a)) is not None
                except re.error:
                    raise FilterError("bad regex")
                return 1 if (m if op == "=~" else not m) else 0
            # string vs number: if either string and other not numeric string compare as strings for equality
            if isinstance(a, str) or isinstance(b, str):
                # numeric comparison if both look numeric
                def isnum(x):
                    if isinstance(x, (int, float)): return True
                    try: float(x); return True
                    except Exception: return False
                if isnum(a) and isnum(b):
                    a2 = float(a); b2 = float(b)
                else:
                    a2 = str(a); b2 = str(b)
            else:
                a2 = a; b2 = b
            if op == "==": return 1 if a2 == b2 else 0
            if op == "!=": return 1 if a2 != b2 else 0
            if op == "<": return 1 if a2 < b2 else 0
            if op == "<=": return 1 if a2 <= b2 else 0
            if op == ">": return 1 if a2 > b2 else 0
            if op == ">=": return 1 if a2 >= b2 else 0
        raise FilterError("bad node")

