MASK=0xffffffff
def x31(s):
    h=0
    for c in s.encode(): h=((h*31)+c)&MASK
    return h
def wang(key):
    key&=MASK
    key=(key + (~(key<<15)))&MASK; key^=key>>10; key=(key+(key<<3))&MASK; key^=key>>6; key=(key + (~(key<<11)))&MASK; key^=key>>16; return key&MASK
seed=42
