def cmd_flags(args):
    if not args:
        d = captured("flags", "noargs")
        if d: _write_out(d["out"]); return d["exit"]
        return 0
    out_lines = []
    for a in args:
        # parse as int (dec/hex/oct) if it looks numeric, else names
        val = None; ok = True
        s = a
        if re.fullmatch(r"[+-]?0[xX][0-9a-fA-F]+", s):
            val = int(s, 16)
        elif re.fullmatch(r"\d+", s):
            # octal if leading 0 and length>1 and all oct digits? hts uses strtol base0
            if len(s) > 1 and s[0] == "0":
                try: val = int(s, 8)
                except Exception: ok = False
            else:
                val = int(s, 10)
        elif re.fullmatch(r"0[0-7]+", s):
            val = int(s, 8)
        else:
            # comma separated names (case-sensitive? hts is case?) try exact
            parts = s.split(",")
            v = 0; ok2 = True
            for p in parts:
                if p in FLAG_BY_NAME:
                    v |= FLAG_BY_NAME[p]
                else:
                    ok2 = False; break
            if ok2:
                val = v
            else:
                ok = False
        if not ok or val is None:
            d = captured("flags", "badlong")
            body = ""
            if d:
                txt = d.get("err") or ""
