                txt = txt.replace('"--__nosuchopt__"', f'"{a}"', 1)
                body = txt
            else:
                body = f'samtools flags: Could not parse "{a}"\n'
            raise HelpExit("", body, 1)
        names = [n for v, n, _ in FLAG_DEFS if val & v]
        # Bits outside known? hts shows only known names
        out_lines.append(f"0x{val:x}\t{val}\t{','.join(names)}")
    sys.stdout.write("\n".join(out_lines) + "\n")
    return 0

