def _is_bgzf_file(path):
    try:
        with open(path, "rb") as fh:
            head = fh.read(18)
        return len(head) >= 18 and head[0] == 0x1f and head[1] == 0x8b and head[3] & 4 and b"BC" in head[12:18]
    except Exception:
        return False

def _ensure_fai(path, is_fastq=False, fai_path=None, gzi_path=None, cmd="faidx"):
    fai = fai_path or (path + ".fai")
    if os.path.exists(fai):
        return fai, False
    # need build
    if not os.path.exists(path):
        raise SamtoolsError(f"[E::fai_build3_core] Failed to open the file {path} : No such file or directory\n[{cmd}] Could not build fai index {fai}\n")
    # plain gzip cannot be indexed
    is_gz = False
    try:
        with open(path, "rb") as fh:
            magic = fh.read(2)
        is_gz = magic == b"\x1f\x8b"
    except Exception:
        pass
    if is_gz and not _is_bgzf_file(path):
        raise SamtoolsError(
            f"[E::fai_build_core] File truncated at line 1\n"
            f"[E::fai_build3_core] Cannot index files compressed with gzip, please use bgzip\n"
            f"[{cmd}] Could not load fai index {fai}\n")
    entries, raw_gz = build_fai(path, is_fastq=is_fastq)
    write_fai(fai, entries)
    if is_gz:
        gzpath = gzi_path or (path + ".gzi")
        write_gzi(path, gzpath)
    return fai, True

