def parse_remove_tags(remove_specs, keep_specs):
    """Return (remove_set, keep_set or None). Handles ^ prefix."""
    remove = set(); keep = None
    for spec in (remove_specs or []):
        for item in str(spec).split(","):
            item = item.strip()
            if not item: continue
            if item.startswith("^"):
                if keep is None: keep = set()
                keep.add(item[1:])
            else:
                remove.add(item)
    for spec in (keep_specs or []):
        for item in str(spec).split(","):
            item = item.strip()
            if item:
                if keep is None: keep = set()
                keep.add(item.lstrip("^"))
    return remove, keep

