            cnt = 0
            while seq_ops and cnt < n:
                last = seq_ops.pop()
                if last[0] in "MIS=X":
                    cnt += 1
            q -= n; rpos -= n
            if q < 0: q = 0
            if rpos < 0: rpos = 0
