def parse_remove_tags(remove_specs, keep_specs):
    """Return (remove_set, keep_set or None). Handles ^ prefix."""
    remove = set(); keep = None
    for spec in (remove_specs or []):
        for item in str(spec).split(","):
            item = item.strip()
            if not item: continue
            if item.startswith("^"):
                if keep is None: keep = set()
                keep.add(item[1:])
            else:
                remove.add(item)
    for spec in (keep_specs or []):
        for item in str(spec).split(","):
            item = item.strip()
            if item:
                if keep is None: keep = set()
                keep.add(item.lstrip("^"))
    return remove, keep

def build_rg_maps(header):
    rg_lb = {}
    rg_sm = {}
    for ln in header.lines:
        if ln.startswith("@RG"):
            _, tags, _ = parse_header_line(ln)
            if "ID" in tags:
                if "LB" in tags: rg_lb[tags["ID"]] = tags["LB"]
                if "SM" in tags: rg_sm[tags["ID"]] = tags["SM"]
    return rg_lb, rg_sm

def file_lines_set(path):
    out = set()
    with open(path) as fh:
        for ln in fh:
            v = ln.strip()
            if v: out.add(v)
    return out

def parse_maybe_negated_file(spec):
    neg = False; p = spec
    if p.startswith("^"):
        neg = True; p = p[1:]
    return neg, p

class ViewFilter:
    def __init__(self, vals, header):
        self.vals = vals; self.header = header
