        # flags values parsed later lazily (allow strings)
    def _flag(self, key, default=0):
        v = self.vals.get(key)
        if v is None: return default
        return parse_flag_value(v)
    def passes(self, rec):
        vals = self.vals
        # MAPQ
        if vals.get("min_MQ") is not None and rec.mapq < int(vals["min_MQ"]):
            return False
        if vals.get("min_qlen") is not None:
            q = rec.query_len_cigar() if rec.cigar else rec.seq_len()
            if q < int(vals["min_qlen"]):
                return False
