            return False
        excl = self._flag("exclude_flags", 0)
        if excl and (rec.flag & excl) != 0:
            return False
        incl = 0
        for key in ("incl_flags",):
            if vals.get(key) is not None:
                incl = self._flag(key, 0)
        if incl and (rec.flag & incl) == 0:
            return False
        gexcl = self._flag("exclude_all_flags", 0)
        if gexcl and (rec.flag & gexcl) == gexcl:
            return False
        # qname file
        if self.qnames is not None:
            inside = rec.qname in self.qnames
            if inside == self.qnames_neg:
                return False
        # read group
        if self.rg_set is not None or vals.get("exclude_no_rg"):
            rg = rec.get_tag("RG")
            if rg is None:
                if vals.get("exclude_no_rg"):
                    return False
                if self.rg_set is not None and getattr(self, "rg_neg", False):
                    pass  # no-RG still passes for negated file? "or in none" applies
                # For -r/-R without -n, no RG passes
            else:
                if self.rg_set is not None:
                    inside = str(rg) in self.rg_set
                    if getattr(self, "rg_neg", False):
                        if inside: return False
                    else:
                        if not inside: return False
        if vals.get("library"):
            rg = rec.get_tag("RG")
