        if self.tag_filters:
            tag = self.tag_filters[0][0]
            tg = rec.get_tag_typed(tag)
            if tg is None:
                return False
            wanted = [v for _, v in self.tag_filters]
            if any(v is None for v in wanted):
                pass
            else:
                typ, v = tg
                if typ == "B":
                    return False
                if str(v) not in wanted:
                    # float string formats
                    ok = False
                    for w in wanted:
                        try:
                            if float(v) == float(w): ok = True
                        except Exception: pass
                    if not ok: return False
        for tag, wset in self.tag_file_filters:
            tg = rec.get_tag_typed(tag)
            if tg is None:
                return False
            typ, v = tg
            if str(v) not in wset:
                return False
        # bed overlap (for -L without -M; also used as region filter)
        if self.beds and not self.vals.get("_beds_handled_by_regions"):
            if not any(record_overlaps_region(rec, c, s, e) for c, s, e in self.beds):
                return False
        if vals.get("subsample") is not None:
            frac = float(vals["subsample"])
            seed = int(vals.get("subsample_seed", 0) or 0)
            if not subsample_keep(rec.qname, frac, seed):
                return False
        if self.expr is not None:
            try:
                if not self.expr.eval(rec, self.header):
                    return False
            except FilterError as ex:
                # distinguish B tag special message handled by caller
