        return True

def process_record_view(rec, vals, remove_set, keep_set):
    r = rec.copy()
    # add/remove flags
    if vals.get("add_flags") is not None:
        try: delta = vals["add_flags"]
        except Exception: delta = None
        # may be multi list
        vals_list = delta if isinstance(delta, list) else [delta]
        for d in vals_list:
            if d is not None: r.flag |= parse_flag_value(d)
    if vals.get("remove_flags") is not None:
        delta = vals["remove_flags"]
        vals_list = delta if isinstance(delta, list) else [delta]
        for d in vals_list:
            if d is not None: r.flag &= ~parse_flag_value(d)
    # tags
    if keep_set is not None:
        r.tags = [tg for tg in r.tags if tg[0] in keep_set]
    if remove_set:
        r.tags = [tg for tg in r.tags if tg[0] not in remove_set]
    # -B remove backward cigar
    if vals.get("remove_B") and any(op == "B" for _, op in r.cigar):
        r.cigar = collapse_backward_cigar(r.cigar)
    return r

def collapse_backward_cigar(cigar):
    # Remove B ops by rewinding: to a first approximation we replay operations
    # tracking q/r positions and truncate back. This is rarely exercised.
    # Build aligned segments as list of ops, cutting back on B.
    out = []
    # expand to per-base ops with positions
    q = 0; rpos = 0; seq_ops = []  # list of (op,qpos,rpos)
    for n, op in cigar:
        if op == "B":
            # remove last n query-consuming ops
            cnt = 0
            while seq_ops and cnt < n:
                last = seq_ops.pop()
                if last[0] in "MIS=X":
                    cnt += 1
            q -= n; rpos -= n
            if q < 0: q = 0
            if rpos < 0: rpos = 0
            continue
        for _ in range(n):
            seq_ops.append((op, q, rpos))
            if op in "MIS=X": q += 1
            if op in "MDN=X": rpos += 1
    # compress
    for op, _, _ in seq_ops:
        if out and out[-1][1] == op:
            out[-1] = (out[-1][0] + 1, op)
        else:
            out.append((1, op))
    return out

