def collapse_backward_cigar(cigar):
    # Remove B ops by rewinding: to a first approximation we replay operations
    # tracking q/r positions and truncate back. This is rarely exercised.
    # Build aligned segments as list of ops, cutting back on B.
    out = []
    # expand to per-base ops with positions
    q = 0; rpos = 0; seq_ops = []  # list of (op,qpos,rpos)
    for n, op in cigar:
        if op == "B":
            # remove last n query-consuming ops
            cnt = 0
            while seq_ops and cnt < n:
                last = seq_ops.pop()
                if last[0] in "MIS=X":
                    cnt += 1
            q -= n; rpos -= n
            if q < 0: q = 0
            if rpos < 0: rpos = 0
            continue
        for _ in range(n):
            seq_ops.append((op, q, rpos))
            if op in "MIS=X": q += 1
            if op in "MDN=X": rpos += 1
    # compress
    for op, _, _ in seq_ops:
        if out and out[-1][1] == op:
            out[-1] = (out[-1][0] + 1, op)
        else:
            out.append((1, op))
    return out

