# ------------------------------------------------------------- fixmate etc
def _mate_end(rec):
    return rec.end_pos_excl()  # 0-based exclusive; pos1-1+span

def _fix_pair(a, b, add_ms=False, add_ct=False, disable_proper=False):
    """Apply fixmate logic to two records (in place copies assumed)."""
    # Remove existing mate-related tags (will re-add)
    for r in (a, b):
        for t in ("MQ", "MC", "ms", "ct"):
            r.del_tag(t)
    # If a read is unmapped without coordinate, place it at mate coordinate
    for r, m in ((a, b), (b, a)):
        if r.is_unmapped() and r.rname in ("*", "") and m.rname not in ("*", ""):
            r.rname = m.rname; r.pos = m.pos
    # TLEN
    if (not a.is_unmapped() and not b.is_unmapped() and a.rname == b.rname and a.rname not in ("*", "") and a.pos > 0 and b.pos > 0):
        a_end = _mate_end(a); b_end = _mate_end(b)  # 0-based exclusive
        left_pos0 = min(a.pos, b.pos) - 1
        right_end = max(a_end, b_end)
        isize = right_end - left_pos0
        # leftmost gets +, rightmost -; tie: first encountered? use pos then end
        if a.pos < b.pos or (a.pos == b.pos and a_end <= b_end):
            a.tlen = isize; b.tlen = -isize
        else:
            a.tlen = -isize; b.tlen = isize
    else:
        a.tlen = 0; b.tlen = 0
    # proper pair (FR check)
    proper = False
    if (not disable_proper and not a.is_unmapped() and not b.is_unmapped()
            and a.rname == b.rname and a.rname not in ("*", "")):
        if a.pos < b.pos:
            proper = (not a.is_reverse()) and b.is_reverse()
        elif b.pos < a.pos:
            proper = (not b.is_reverse()) and a.is_reverse()
        else:
            proper = (a.is_reverse() != b.is_reverse())
    for r, m in ((a, b), (b, a)):
        r.flag |= 0x1  # paired
        r.flag &= ~0x2
        if proper: r.flag |= 0x2
        if m.is_unmapped(): r.flag |= 0x8
        else: r.flag &= ~0x8
        if m.is_reverse(): r.flag |= 0x20
        else: r.flag &= ~0x20
        # mate coordinates
        if m.rname in ("*", ""):
            r.rnext = "*"; r.pnext = 0
        else:
            r.rnext = "=" if m.rname == r.rname else m.rname
            r.pnext = m.pos
        # tags MQ, MC, ms in this order
        if not m.is_unmapped():
            r.set_tag("MQ", "i", m.mapq)
            if m.cigar:
                r.set_tag("MC", "Z", cigar_to_str(m.cigar))
        if add_ms:
            score = sum(q for q in m.qual_list())
            r.set_tag("ms", "i", int(score))
        if add_ct:
            # Combined template cigar approximation: left cigar, gap, right cigar
            left, right = (a, b) if a.pos <= b.pos else (b, a)
            if left.rname == right.rname and left.cigar and right.cigar and left.pos > 0 and right.pos > 0:
                gap = (right.pos - 1) - _mate_end(left)
                parts = [cigar_to_str(left.cigar)]
                if gap > 0: parts.append(f"{gap}N")
                parts.append(cigar_to_str(right.cigar))
                r.set_tag("ct", "Z", "".join(parts))
    return a, b

def cmd_fixmate(args):
    spec = [S("remove", short="r"), S("disable_proper", short="p"), S("add_ct", short="c"),
            S("add_ms", short="m"), S("uncompressed_flag", short="u"),
            S("sanitize", short="z", long="sanitize", arg=True),
            S("fix_mod_tags", short="M"), S("no_PG", long="no-PG")] + global_opts()
    # fixmate supports --reference but not -T short in help (global has -T; harmless)
    vals, pos = OptParser("fixmate", spec).parse(args)
    if len(pos) < 2:
        usage_noargs("fixmate")
    in_path, out_path = pos[0], pos[1]
    data = load_alignments(in_path, "fixmate", ref_path=vals.get("reference"))
    records = [r.copy() for r in data.records]
    if vals.get("remove"):
        records = [r for r in records if not (r.is_unmapped() or r.is_secondary())]
    out_recs = []
    i = 0
    while i < len(records):
        j = i + 1
        while j < len(records) and records[j].qname == records[i].qname:
            j += 1
        group = records[i:j]
        # candidate primary pair
        primaries = [idx for idx, r in enumerate(group) if not r.is_secondary() and not r.is_supplementary()]
        pair_idx = []
        if len(primaries) >= 2:
            r1 = [idx for idx in primaries if group[idx].flag & 0x40]
            r2 = [idx for idx in primaries if group[idx].flag & 0x80]
            if r1 and r2 and r1[0] != r2[0]:
                pair_idx = [r1[0], r2[0]]
            else:
                pair_idx = primaries[:2]
        if len(pair_idx) == 2:
            a, b = group[pair_idx[0]], group[pair_idx[1]]
            _fix_pair(a, b, add_ms=bool(vals.get("add_ms")), add_ct=bool(vals.get("add_ct")),
                      disable_proper=bool(vals.get("disable_proper")))
            # other records: point them at the mate of their segment
            pair_by_seg = {}
            for rec in (a, b):
                if rec.flag & 0x40: pair_by_seg["1"] = rec
                if rec.flag & 0x80: pair_by_seg["2"] = rec
            for idx, r in enumerate(group):
                if idx in pair_idx: continue
                # determine mate
                mate = None
                if r.flag & 0x40: mate = pair_by_seg.get("2", b)
                elif r.flag & 0x80: mate = pair_by_seg.get("1", a)
                else: mate = b if r is not b else a
                if r.is_unmapped() and r.rname in ("*", "") and mate.rname not in ("*", ""):
                    r.rname = mate.rname; r.pos = mate.pos
                r.flag |= 0x1
                r.flag &= ~0x2
                if mate.is_unmapped(): r.flag |= 0x8
                else: r.flag &= ~0x8
                if mate.is_reverse(): r.flag |= 0x20
                else: r.flag &= ~0x20
                if mate.rname in ("*", ""):
                    r.rnext = "*"; r.pnext = 0
                else:
                    r.rnext = "=" if mate.rname == r.rname else mate.rname
                    r.pnext = mate.pos
                for t in ("MQ", "MC", "ms", "ct"): r.del_tag(t)
                if not mate.is_unmapped():
                    r.set_tag("MQ", "i", mate.mapq)
                    if mate.cigar: r.set_tag("MC", "Z", cigar_to_str(mate.cigar))
                if vals.get("add_ms"):
                    r.set_tag("ms", "i", int(sum(mate.qual_list())))
        else:
            # singleton groups: if paired flag set but no mate, set mate-unmapped
            for r in group:
                if r.is_paired():
                    r.flag |= 0x8
                    r.flag &= ~0x2
                    # htslib leaves RNEXT/PNEXT as-is for orphan? If mate fields empty leave.
                for t in ("MQ", "MC", "ms"):
                    # Only remove if no mate in group (singletons) - observed unpaired originals had none
                    if len(group) == 1 and r.is_paired():
                        r.del_tag(t)
                if r.is_unmapped() and r.rnext not in ("*", "=") and r.pnext == 0:
                    pass
        out_recs.extend(group)
        i = j
    comp = 0 if vals.get("uncompressed_flag") else 6
    efmt, _ = parse_output_fmt(vals.get("output_fmt"))
    v2 = dict(vals); v2["fmt_explicit"] = efmt
    output_alignments(out_path, data.header, out_recs, v2, default_stdout="BAM", compression_level=comp, argv=ORIGINAL_ARGV)
    return 0

def _ambiguous_match(read_base, ref_base):
    a = read_base.upper(); b = ref_base.upper()
    if a == "=": return True
    if a == b: return True
    amap = {"A":"A","C":"C","G":"G","T":"T","U":"T","R":"AG","Y":"CT","S":"GC","W":"AT","K":"GT","M":"AC","B":"CGT","D":"AGT","H":"ACT","V":"ACG","N":"ACGT"}
    return bool(set(amap.get(a, a)) & set(amap.get(b, b)))

def compute_md_nm(rec, refseq, make_equal=False):
    """Return (md, nm, new_seq or None). refseq is full reference string."""
    if rec.pos <= 0 or not rec.cigar or rec.seq == "*":
        return None
    ref = refseq.upper()
    seq = list(rec.seq)
    q = 0; rpos = rec.pos - 1  # 0-based
    md_parts = []; match_count = 0; has_md = False
    nm = 0
    def flush():
        nonlocal match_count
        md_parts.append(str(match_count)); match_count = 0
    for length, op in rec.cigar:
        if op in "M=X":
            for _ in range(length):
                rb = ref[rpos] if 0 <= rpos < len(ref) else "N"
                qb = seq[q] if q < len(seq) else "N"
                if _ambiguous_match(qb, rb):
                    match_count += 1
                    if make_equal and q < len(seq): seq[q] = "="
                    elif qb == "=" and q < len(seq): seq[q] = rb
                else:
                    flush(); md_parts.append(rb); nm += 1
                    if qb == "=" and q < len(seq): seq[q] = rb
                q += 1; rpos += 1
        elif op == "I":
            nm += length; q += length
        elif op == "D":
            flush(); md_parts.append("^")
            deleted = []
            for _ in range(length):
                deleted.append(ref[rpos] if 0 <= rpos < len(ref) else "N"); rpos += 1; nm += 1
            md_parts.append("".join(deleted))
        elif op == "N":
            rpos += length
        elif op == "S":
            q += length
        elif op == "P":
            rpos += length
        elif op == "H":
            pass
        elif op == "B":
            q -= length; rpos -= length
    flush()
    return ("".join(md_parts), nm, "".join(seq))

def cmd_calmd(args):
    # calmd accepts --output-fmt but not -O; build custom globals
    spec = [S("change_equal", short="e"), S("uncompressed_flag", short="u"), S("bam_flag", short="b"),
            S("ignored_S", short="S"), S("modify_qual", short="A"), S("quiet", short="Q"),
            S("compute_baq", short="r"), S("extended_baq", short="E"), S("no_PG", long="no-PG"),
            S("input_fmt_option", long="input-fmt-option", arg=True, multi=True),
            S("output_fmt", long="output-fmt", arg=True),
            S("output_fmt_option", long="output-fmt-option", arg=True, multi=True),
            S("reference", long="reference", arg=True),
            S("threads", short="@", long="threads", arg=True), S("verbosity", long="verbosity", arg=True),
            S("write_index", long="write-index")]
    vals, pos = OptParser("calmd", spec).parse(args)
    if len(pos) < 2:
        usage_noargs("calmd")
    in_path, ref_path = pos[0], pos[1]
    data = load_alignments(in_path, "calmd")
    if not os.path.exists(ref_path):
        raise SamtoolsError(f"[E::fai_build3_core] Failed to open the file {ref_path} : No such file or directory\n", 1)
    refs = {n: s for n, s, d in read_fasta(ref_path)}
    out_recs = []
    for orig in data.records:
        r = orig.copy()
        if r.is_unmapped() or r.rname in ("*", "") or not r.cigar:
            out_recs.append(r); continue
        refseq = refs.get(r.rname)
        if refseq is None:
            out_recs.append(r); continue
        # BAQ (approximation placeholder returns qualities capped concept below)
        baq_vals = None
        if vals.get("compute_baq"):
            try:
                baq_vals = compute_baq(r, refseq, extended=bool(vals.get("extended_baq")))
            except Exception:
                baq_vals = None
        res = compute_md_nm(r, refseq, make_equal=bool(vals.get("change_equal")))
        if res:
            md, nm, newseq = res
            if newseq and r.seq != "*": r.seq = newseq
            if baq_vals is not None:
                if vals.get("modify_qual"):
                    if r.qual != "*":
                        ql = r.qual_list()
                        capped = [min(ql[k], baq_vals[k]) if k < len(baq_vals) else ql[k] for k in range(len(ql))]
                        r.qual = "".join(chr(min(x, 93) + 33) for x in capped)
                else:
                    r.del_tag("BQ")
                    bqstr = "".join(chr(max(0, min(x, 93)) + 33) for x in baq_vals[:r.seq_len()])
                    if r.qual != "*":
                        # BQ only added when original qualities present (toy: reads with * got no BQ)
                        r.tags.append(("BQ", "Z", bqstr))
            r.del_tag("NM"); r.del_tag("MD")
            # htslib appends NM then MD at end (if BQ added above it's before them)
            r.tags.append(("NM", "i", nm)); r.tags.append(("MD", "Z", md))
        out_recs.append(r)
    fmt_explicit = None; comp = 6
    efmt, _ = parse_output_fmt(vals.get("output_fmt"))
    if vals.get("uncompressed_flag"):
        fmt_explicit = "BAM"; comp = 0
    elif vals.get("bam_flag"):
        fmt_explicit = "BAM"
    elif efmt:
        fmt_explicit = efmt
    v2 = dict(vals); v2["fmt_explicit"] = fmt_explicit
    output_alignments(None, data.header, out_recs, v2, default_stdout="SAM", compression_level=comp, argv=ORIGINAL_ARGV)
    return 0

def compute_baq(rec, refseq, extended=False):
    """BAQ approximation.

    Full BAQ uses a pair-HMM of the read against the reference to estimate,
    for each base, Phred-scaled probability that the base is misaligned.
    This implementation performs a banded forward-backward pair-HMM
    alignment (match/insert/delete states) and returns
    -10*log10(P(base is not aligned to the reference base implied by the
    read's CIGAR)).  It is a from-scratch model; values are close in spirit
    to samtools BAQ but may not be byte-identical in every case.
    """
    if rec.qual == "*" or rec.seq == "*" or rec.pos <= 0 or not rec.cigar:
        return None
    # Reference window: from read start (with small flank) to read end
    seq = rec.seq.upper()
    qual = rec.qual_list()
    n = len(seq)
    if n == 0:
        return []
    # Resource guard: very long reads -> fall back to original qualities + margin
    if n > 2000:
        return [min(93, q + 1) for q in qual]
    ref_full = refseq.upper()
    ref_beg = rec.pos - 1
    ref_end = ref_beg + max(rec.ref_span(), 1)
    # Flanks: htslib extends by (bandwidth?) use modest flank
    FLANK = 10
    rb = max(0, ref_beg - FLANK); re_ = min(len(ref_full), ref_end + FLANK)
    ref = ref_full[rb:re_]
    m = len(ref)
    if m == 0:
        return [0] * n
    W = 50  # band half-width in terms of (i-j) offset relative to expected alignment
    # Expected ref index for query base q under input CIGAR (or None for insertions/clips)
    expected = [None] * n
    q_ = 0; rp = ref_beg
    for ln, op in rec.cigar:
        if op in "M=X":
            for _ in range(ln):
                if q_ < n: expected[q_] = rp - rb
                q_ += 1; rp += 1
        elif op in "IS":
            q_ += ln
        elif op in "DN":
            rp += ln
        elif op == "P":
            rp += ln
        elif op == "H":
            pass
        elif op == "B":
            q_ -= ln; rp -= ln
    # Pair-HMM parameters (log10 probabilities converted to natural log)
    import math as _math
    gap_open = 0.001 if not extended else 0.0001  # probabilities of entering I/D
    gap_ext = 0.1 if not extended else 0.3
    # log transition probs (approximate normalisation ignored - absorbed)
    l_go = _math.log(gap_open); l_ge = _math.log(gap_ext); l_mm = _math.log(1 - 2 * gap_open)
    l_im = _math.log(1 - gap_ext); l_dm = _math.log(1 - gap_ext)
    NEG = -1e100
    def logsumexp(vals):
        mx = max(vals)
        if mx == NEG: return NEG
        return mx + _math.log(sum(_math.exp(v - mx) for v in vals))
    # emission log prob for match state M (q aligned to r): based on qual
    emitM = [[NEG] * m for _ in range(n)]
    for i in range(n):
        e = 10 ** (-qual[i] / 10.0) if qual[i] < 255 else 0.001
        e = min(max(e, 1e-6), 0.75)
        p_match = 1 - e; p_mis = e / 3.0
        qi = seq[i]
        row = emitM[i]
        for j in range(m):
            row[j] = _math.log(p_match if qi == ref[j] or qi == "=" else p_mis)
    emitI = []
    for i in range(n):
        e = 10 ** (-qual[i] / 10.0) if qual[i] < 255 else 0.001
        emitI.append(_math.log(0.25))  # insertion emits query base w.p. 1/4
    # Anchoring: we let alignment start at reference offset corresponding to read start +- W
    start_j = ref_beg - rb  # expected column of first aligned ref base
    def allowed(i, j):
        # i: query index (0-based count consumed-1), j ref consumed-1. Diagonal d = j - i
        return abs((j - i) - start_j) <= W
    # Forward arrays indexed [i][j] where i query bases consumed (i in 0..n uses prob after consuming)
    # We use dict rows for speed with banding.
    from collections import defaultdict as _dd
    fM = [dict() for _ in range(n + 1)]; fI = [dict() for _ in range(n + 1)]; fD = [dict() for _ in range(n + 1)]
    # Initial: before any bases, alignment can open deletions near start? Initialise M at (0, start_j-1) prob 1
    # Represent j as last ref base consumed index; start position j0 = start_j-1.
    fM[0][start_j - 1] = 0.0
    for i in range(n + 1):
        # process D transitions iteratively within row
        # compute M and I for i from previous row
        if i > 0:
            prevM, prevI, prevD = fM[i-1], fI[i-1], fD[i-1]
            # M[i][j] from (i-1, j-1) any state
            js = set()
