                if j - 1 in prevI: vals.append(prevI[j-1] + l_im)
                if j - 1 in prevD: vals.append(prevD[j-1] + l_dm)
                if vals:
                    fM[i][j] = logsumexp(vals) + emitM[i-1][j]
