            js2 = set(list(prevM.keys()) + list(prevI.keys()))
            for j in js2:
                if j < -1 or j >= m: continue
                vals = []
                if j in prevM: vals.append(prevM[j] + l_go)
                if j in prevI: vals.append(prevI[j] + l_ge)
                if vals:
                    fI[i][j] = logsumexp(vals) + emitI[i-1]
