            vals = []
            if j + 1 < m and (j + 1) in bD[i]:
                vals.append(l_ge + bD[i][j+1])
            if j + 1 < m and (j + 1) in bM[i+1]:
                vals.append(l_dm + emitM[i][j+1] + bM[i+1][j+1])
            if vals: bD[i][j] = logsumexp(vals)
