                vals.append(l_im + emitM[i][j+1] + bM[i+1][j+1])
            if j in bI[i+1]:
                vals.append(l_ge + emitI[i] + bI[i+1][j])
            if vals: bI[i][j] = logsumexp(vals)
    out = []
    for i in range(n):
        if expected[i] is None:
            out.append(0); continue
        j = expected[i]
