            out.append(0); continue
        lp = fM[i+1][j] + bM[i+1][j] - total
        p = _math.exp(lp) if lp > -700 else 0.0
        p_err = 1.0 - p
        if p_err <= 0:
            out.append(93)
        else:
            qv = int(round(-10 * _math.log10(p_err)))
            out.append(max(0, min(93, qv)))
    return out

