def _mate_end(rec):
    return rec.end_pos_excl()  # 0-based exclusive; pos1-1+span

def _fix_pair(a, b, add_ms=False, add_ct=False, disable_proper=False):
    """Apply fixmate logic to two records (in place copies assumed)."""
    # Remove existing mate-related tags (will re-add)
    for r in (a, b):
        for t in ("MQ", "MC", "ms", "ct"):
            r.del_tag(t)
    # If a read is unmapped without coordinate, place it at mate coordinate
    for r, m in ((a, b), (b, a)):
        if r.is_unmapped() and r.rname in ("*", "") and m.rname not in ("*", ""):
            r.rname = m.rname; r.pos = m.pos
    # TLEN
    if (not a.is_unmapped() and not b.is_unmapped() and a.rname == b.rname and a.rname not in ("*", "") and a.pos > 0 and b.pos > 0):
        a_end = _mate_end(a); b_end = _mate_end(b)  # 0-based exclusive
        left_pos0 = min(a.pos, b.pos) - 1
        right_end = max(a_end, b_end)
        isize = right_end - left_pos0
        # leftmost gets +, rightmost -; tie: first encountered? use pos then end
        if a.pos < b.pos or (a.pos == b.pos and a_end <= b_end):
            a.tlen = isize; b.tlen = -isize
        else:
            a.tlen = -isize; b.tlen = isize
    else:
        a.tlen = 0; b.tlen = 0
    # proper pair (FR check)
    proper = False
    if (not disable_proper and not a.is_unmapped() and not b.is_unmapped()
            and a.rname == b.rname and a.rname not in ("*", "")):
        if a.pos < b.pos:
            proper = (not a.is_reverse()) and b.is_reverse()
        elif b.pos < a.pos:
            proper = (not b.is_reverse()) and a.is_reverse()
        else:
            proper = (a.is_reverse() != b.is_reverse())
    for r, m in ((a, b), (b, a)):
        r.flag |= 0x1  # paired
        r.flag &= ~0x2
        if proper: r.flag |= 0x2
        if m.is_unmapped(): r.flag |= 0x8
        else: r.flag &= ~0x8
        if m.is_reverse(): r.flag |= 0x20
        else: r.flag &= ~0x20
        # mate coordinates
        if m.rname in ("*", ""):
            r.rnext = "*"; r.pnext = 0
        else:
            r.rnext = "=" if m.rname == r.rname else m.rname
            r.pnext = m.pos
        # tags MQ, MC, ms in this order
        if not m.is_unmapped():
            r.set_tag("MQ", "i", m.mapq)
            if m.cigar:
                r.set_tag("MC", "Z", cigar_to_str(m.cigar))
        if add_ms:
            score = sum(q for q in m.qual_list())
            r.set_tag("ms", "i", int(score))
