            # Combined template cigar approximation: left cigar, gap, right cigar
            left, right = (a, b) if a.pos <= b.pos else (b, a)
            if left.rname == right.rname and left.cigar and right.cigar and left.pos > 0 and right.pos > 0:
                gap = (right.pos - 1) - _mate_end(left)
                parts = [cigar_to_str(left.cigar)]
                if gap > 0: parts.append(f"{gap}N")
                parts.append(cigar_to_str(right.cigar))
                r.set_tag("ct", "Z", "".join(parts))
    return a, b

