    import math as _math
    gap_open = 0.001 if not extended else 0.0001  # probabilities of entering I/D
    gap_ext = 0.1 if not extended else 0.3
    # log transition probs (approximate normalisation ignored - absorbed)
    l_go = _math.log(gap_open); l_ge = _math.log(gap_ext); l_mm = _math.log(1 - 2 * gap_open)
    l_im = _math.log(1 - gap_ext); l_dm = _math.log(1 - gap_ext)
