def _header_from_file(path):
    if path == "-":
        text = sys.stdin.read()
    else:
        data = _read_file_bytes(path)
        dec, _ = open_maybe_gzip_bytes(data)
        # If file is BAM, extract its header
        if dec[:4] == b"BAM\x01":
            h, _ = decode_bam(dec, None); return h
        text = dec.decode(errors="replace")
    lines = []
    for ln in text.splitlines():
        if ln.startswith("@"):
            lines.append(ln)
        else:
            break
    return Header(lines)

def cmd_reheader(args):
    spec = [S("help_", short="h", long="help", help="--help"),
