        if proc.returncode != 0:
            raise SamtoolsError(f"reheader: command failed with exit status {proc.returncode}\n", 1)
        lines = [l for l in proc.stdout.splitlines() if l.startswith("@")]
        new_header = Header(lines)
    else:
        if len(pos) < 2: usage_noargs("reheader")
        hdr_path, in_path = pos[0], pos[1]
        if not os.path.exists(hdr_path) and hdr_path != "-":
            raise SamtoolsError(f"reheader: cannot open {hdr_path}: No such file or directory\n", 1)
