    out_recs = []
    def remap(name):
        if name in ("*", "=", ""): return name
        i = old_idx.get(name)
        if i is not None and i < len(new_refs):
            return new_refs[i][0]
        return name
    for orig in data.records:
        r = orig.copy()
        r.rname = remap(r.rname)
        r.rnext = remap(r.rnext)
        out_recs.append(r)
    out_header = new_header.copy()
    if not vals.get("no_PG"):
        out_header.add_pg(list(ORIGINAL_ARGV))
    # Output format = input format (BAM stays BAM, SAM stays SAM)
    fmt = data.fmt if data.fmt in ("SAM", "BAM") else "BAM"
    write_alignments(None, out_header, out_recs, fmt=fmt, with_header=True)
