    else:
        basename_noext = basename
    groups = OrderedDict()  # key -> (index, [records])
    leftovers = []
    tag = vals.get("tag")
    max_split = int(vals.get("max_split", 100)) if vals.get("max_split") else 100
    rg_ids = []
    if not tag:
        for ln in data.header.lines:
            if ln.startswith("@RG"):
                _, tg, _ = parse_header_line(ln)
                if "ID" in tg: rg_ids.append(tg["ID"])
        rg_index = {rid: i for i, rid in enumerate(rg_ids)}
    counter = 0
    for r in data.records:
        key = None; idx = None
        if tag:
            v = r.get_tag(tag)
            if v is not None:
                key = str(v)
                if key not in groups:
                    if tag and len(groups) >= max_split:
                        leftovers.append(r); continue
                    idx = counter; counter += 1
                    groups[key] = (idx, [])
        else:
            rg = r.get_tag("RG")
            if rg is not None and str(rg) in rg_index:
                key = str(rg); idx = rg_index[key]
                if key not in groups:
                    groups[key] = (idx, [])
        if key is None:
            leftovers.append(r)
        else:
            groups[key][1].append(r)
    def expand(idx, key):
        s = fmt_str
        idx_s = str(idx).rjust(pad, "0") if pad else str(idx)
        s = s.replace("%%", "\x00").replace("%*", basename_noext).replace("%#", idx_s).replace("%!", key).replace("%.", ext)
        return s.replace("\x00", "%")
    for key, (idx, recs) in groups.items():
        outname = expand(idx, key)
        v2 = dict(vals); v2["fmt_explicit"] = out_fmt
        output_alignments(outname, data.header, recs, v2, default_stdout=out_fmt, argv=ORIGINAL_ARGV)
        if vals.get("verbose"):
            eprint(outname)
    if leftovers and vals.get("unaccounted"):
        hdr = data.header
        if vals.get("unaccounted_header"):
            hdr = _header_from_file(vals["unaccounted_header"])
        v2 = dict(vals)
        # format from unaccounted filename else efmt
        output_alignments(vals["unaccounted"], hdr, leftovers, v2, default_stdout=out_fmt, argv=ORIGINAL_ARGV)
    return 0

def cmd_collate(args):
