            S("n_tmp", short="n", arg=True), S("tmp_prefix", short="T", arg=True),
            S("no_PG", long="no-PG")] + global_opts()
    vals, pos = OptParser("collate", spec).parse(args)
    if not pos:
        usage_noargs("collate")
    if vals.get("to_stdout") and vals.get("output"):
        usage_error("collate", "collate: -o and -O options cannot be used together.")
    in_path = pos[0]; prefix = pos[1] if len(pos) > 1 else None
    if not vals.get("to_stdout") and not vals.get("output") and not prefix:
        usage_error("collate", "collate: no input filename specified.")
    data = load_alignments(in_path, "collate", ref_path=vals.get("reference"))
    header = data.header.copy()
    header.set_hd(SO="unsorted", SS=None, GO="query")
    if "VN" not in (header.get_hd("VN") or ""):
        pass
    records = data.records
    out_recs = []
    if vals.get("fast"):
        buffer_n = int(vals.get("buffer", 10000)) if vals.get("buffer") else 10000
        buf = OrderedDict()
        for r in records:
            if r.is_secondary() or r.is_supplementary():
                continue
            q = r.qname
            if q in buf:
                mate = buf.pop(q)
                out_recs.extend([mate, r])
            else:
                buf[q] = r
                if len(buf) > buffer_n:
                    buf.popitem(last=False)  # discard oldest singleton
        # remaining singletons discarded in fast mode (observed)
    else:
        groups = OrderedDict()
        for r in records:
            groups.setdefault(r.qname, []).append(r)
        for q, recs in groups.items():
            out_recs.extend(recs)
    comp = 1
    if vals.get("compression") is not None:
        try: comp = int(vals["compression"])
        except Exception: pass
    if vals.get("uncompressed_flag"): comp = 0
    out_path = None if vals.get("to_stdout") else vals.get("output")
    if not vals.get("to_stdout") and not out_path and prefix:
        out_path = prefix if os.path.splitext(prefix)[1] in (".bam", ".sam", ".cram") else prefix + ".bam"
    efmt, _ = parse_output_fmt(vals.get("output_fmt"))
    v2 = dict(vals); v2["fmt_explicit"] = efmt
    output_alignments(out_path, header, out_recs, v2, default_stdout="BAM", compression_level=comp, argv=ORIGINAL_ARGV)
    return 0

