def cmd_addreplacerg(args):
    spec = [S("help_", short="h", help="-h"),
            S("mode", short="m", arg=True), S("output", short="o", arg=True),
            S("rg_line", short="r", arg=True), S("rg_existing", short="R", arg=True),
            S("uncompressed_flag", short="u"), S("overwrite", short="w"),
            S("input_fmt", long="input-fmt", arg=True)] + global_opts()
    vals, pos = OptParser("addreplacerg", spec).parse(args)
    if not pos or (not vals.get("rg_line") and not vals.get("rg_existing")):
        usage_noargs("addreplacerg")
    in_path = pos[0]
    data = load_alignments(in_path, "addreplacerg", ref_path=vals.get("reference"))
    header = data.header.copy()
    mode = vals.get("mode", "overwrite_all")
    if mode not in ("overwrite_all", "orphan_only"):
        raise SamtoolsError(f"[addreplacerg] invalid mode: {mode}\n", 1)
    if vals.get("rg_existing"):
        rg_id = vals["rg_existing"]
        found = False
        for ln in header.lines:
            if ln.startswith("@RG"):
                _, tags, _ = parse_header_line(ln)
                if tags.get("ID") == rg_id: found = True
        if not found:
            raise SamtoolsError(f"There is no @RG line with ID:{rg_id} in the header.\n", 1)
    else:
        text = vals["rg_line"]
        # convert literal \t escapes
        text = text.replace("\\t", "\t")
        if text.startswith("@RG"):
            line = text
        elif text.startswith("ID:") or "\t" in text:
            line = "@RG\t" + text
        else:
            # ERR: maybe string is just ID? samtools requires ID: prefix
            line = "@RG\t" + text
        _, tags, _ = parse_header_line(line)
        if "ID" not in tags:
            raise SamtoolsError("@RG line does not have an ID.\n", 1)
        rg_id = tags["ID"]
        existing_idx = None
        for i, ln in enumerate(header.lines):
            if ln.startswith("@RG"):
                _, t2, _ = parse_header_line(ln)
                if t2.get("ID") == rg_id: existing_idx = i
        if existing_idx is not None:
            if header.lines[existing_idx] != line:
                if vals.get("overwrite"):
                    header.lines[existing_idx] = line
                else:
                    raise SamtoolsError(f"An @RG line with ID:{rg_id} already exists and -w was not used.\n", 1)
        else:
            header.lines.append(line)
    out_recs = []
    for orig in data.records:
        r = orig.copy()
        if mode == "overwrite_all" or not r.has_tag("RG"):
            r.del_tag("RG"); r.tags.append(("RG", "Z", rg_id))
        out_recs.append(r)
    comp = 0 if vals.get("uncompressed_flag") else 6
    efmt, _ = parse_output_fmt(vals.get("output_fmt"))
    v2 = dict(vals); v2["fmt_explicit"] = efmt
    out_path = vals.get("output")
    output_alignments(out_path, header, out_recs, v2, default_stdout="BAM", compression_level=comp, argv=ORIGINAL_ARGV)
    return 0

def _header_from_file(path):
    if path == "-":
        text = sys.stdin.read()
    else:
        data = _read_file_bytes(path)
        dec, _ = open_maybe_gzip_bytes(data)
        # If file is BAM, extract its header
        if dec[:4] == b"BAM\x01":
            h, _ = decode_bam(dec, None); return h
        text = dec.decode(errors="replace")
    lines = []
    for ln in text.splitlines():
        if ln.startswith("@"):
            lines.append(ln)
        else:
            break
    return Header(lines)

def cmd_reheader(args):
    spec = [S("help_", short="h", long="help", help="--help"),
            S("no_PG", short="P", long="no-PG"), S("in_place", short="i", long="in-place"),
            S("command", short="c", long="command", arg=True),
            S("verbosity", long="verbosity", arg=True), S("reference", long="reference", arg=True),
            S("input_fmt_option", long="input-fmt-option", arg=True, multi=True)]
    vals, pos = OptParser("reheader", spec).parse(args)
    if vals.get("command"):
        if not pos: usage_noargs("reheader")
        in_path = pos[0]
        data = load_alignments(in_path, "reheader")
        proc = subprocess.run(vals["command"], shell=True, input=data.header.text(),
                              stdout=subprocess.PIPE, stderr=None, text=True)
        if proc.returncode != 0:
            raise SamtoolsError(f"reheader: command failed with exit status {proc.returncode}\n", 1)
        lines = [l for l in proc.stdout.splitlines() if l.startswith("@")]
        new_header = Header(lines)
    else:
        if len(pos) < 2: usage_noargs("reheader")
        hdr_path, in_path = pos[0], pos[1]
        if not os.path.exists(hdr_path) and hdr_path != "-":
            raise SamtoolsError(f"reheader: cannot open {hdr_path}: No such file or directory\n", 1)
        new_header = _header_from_file(hdr_path)
        data = load_alignments(in_path, "reheader")
    if vals.get("in_place"):
        raise SamtoolsError("reheader: in-place editing is only supported for CRAM files\n", 1)
    old_refs = data.header.refs; new_refs = new_header.refs
    old_idx = {n: i for i, (n, _) in enumerate(old_refs)}
    out_recs = []
    def remap(name):
        if name in ("*", "=", ""): return name
        i = old_idx.get(name)
        if i is not None and i < len(new_refs):
            return new_refs[i][0]
        return name
    for orig in data.records:
        r = orig.copy()
        r.rname = remap(r.rname)
        r.rnext = remap(r.rnext)
        out_recs.append(r)
    out_header = new_header.copy()
    if not vals.get("no_PG"):
        out_header.add_pg(list(ORIGINAL_ARGV))
    # Output format = input format (BAM stays BAM, SAM stays SAM)
    fmt = data.fmt if data.fmt in ("SAM", "BAM") else "BAM"
    write_alignments(None, out_header, out_recs, fmt=fmt, with_header=True)
    return 0

_RESET_REMOVE_TAGS = {"NM","MD","BQ","SA","XS","AS","MQ","MC","ms","NM","UQ","Aq","H0","H1","H2","IH","NH","HI","nM","AS","XS","OQ"}
def cmd_reset(args):
    spec = [S("output", short="o", arg=True),
            S("remove_tag", short="x", long="remove-tag", arg=True, multi=True),
            S("keep_tag", long="keep-tag", arg=True, multi=True),
            S("reject_PG", long="reject-PG", arg=True),
            S("no_RG", long="no-RG"), S("no_PG", long="no-PG"), S("dupflag", long="dupflag"),
            ] + global_opts()
    vals, pos = OptParser("reset", spec).parse(args)
    in_path = pos[0] if pos else "-"
    data = load_alignments(in_path, "reset", ref_path=vals.get("reference"))
    remove_set, keep_set = parse_remove_tags(vals.get("remove_tag") or [], vals.get("keep_tag") or [])
    out_recs = []
    for orig in data.records:
        if orig.is_secondary() or orig.is_supplementary():
            continue
        r = orig.copy()
        was_rev = r.is_reverse()
        # original quality from OQ if present
        oq = r.get_tag("OQ")
        if was_rev and r.seq != "*":
            r.seq = revcomp(r.seq)
            if r.qual != "*": r.qual = r.qual[::-1]
        if oq is not None and isinstance(oq, str):
            r.qual = oq[::-1] if was_rev else oq
        # Hard clips are simply dropped (cannot restore); soft clips become part of unaligned read (they are in SEQ already)
        # Flags
        newflag = 0x4
        if r.flag & 0x1:
            newflag |= 0x1 | 0x8
        if r.flag & 0x40: newflag |= 0x40
        if r.flag & 0x80: newflag |= 0x80
        if r.flag & 0x200: newflag |= 0x200
        if vals.get("dupflag") and (r.flag & 0x400): newflag |= 0x400
        r.flag = newflag
        r.rname = "*"; r.pos = 0; r.mapq = 0; r.cigar = []; r.rnext = "*"; r.pnext = 0; r.tlen = 0
        # tags
        if keep_set is not None:
            r.tags = [tg for tg in r.tags if tg[0] in keep_set]
        else:
            default_rm = set(_RESET_REMOVE_TAGS)
            r.tags = [tg for tg in r.tags if tg[0] not in default_rm]
            if remove_set:
                r.tags = [tg for tg in r.tags if tg[0] not in remove_set]
            if vals.get("no_RG"):
                r.tags = [tg for tg in r.tags if tg[0] != "RG"]
        out_recs.append(r)
    # header: only HD, plus RG lines (unless no-RG), plus surviving PGs
    out_lines = ["@HD\tVN:1.6"]
    if not vals.get("no_RG"):
        for ln in data.header.lines:
            if ln.startswith("@RG"):
                out_lines.append(ln)
    # PG lines with optional rejection
    pg_lines = [ln for ln in data.header.lines if ln.startswith("@PG")]
    reject = vals.get("reject_PG")
    if reject:
        kept = []
        for ln in pg_lines:
            _, tags, _ = parse_header_line(ln)
            if tags.get("ID") == reject:
                break
            kept.append(ln)
        pg_lines = kept
    out_lines += pg_lines
    out_header = Header(out_lines)
    if not vals.get("no_PG"):
        out_header.add_pg(list(ORIGINAL_ARGV))
    efmt, _ = parse_output_fmt(vals.get("output_fmt"))
    v2 = dict(vals); v2["fmt_explicit"] = efmt; v2["no_PG"] = True  # already handled
    output_alignments(vals.get("output"), out_header, out_recs, v2, default_stdout="BAM", add_pg=False, argv=ORIGINAL_ARGV)
    return 0

def cmd_quickcheck(args):
    verbose = 0; quiet = False; unmapped_ok = False; files = []
    for a in args:
        if a.startswith("-") and a != "-":
            for ch in a[1:]:
                if ch == "v": verbose += 1
                elif ch == "q": quiet = True
                elif ch == "u": unmapped_ok = True
                else:
                    usage_error("quickcheck", f"quickcheck: invalid option -- '{ch}'")
        else:
            files.append(a)
    if not files:
        usage_noargs("quickcheck")
    ret = 0
    for path in files:
        failed = False; reasons = []
        try:
            raw = _read_file_bytes(path)
        except Exception:
            failed = True; reasons.append("open"); ret |= 2
            if not quiet: eprint(f"{path} could not be opened for reading.")
            if verbose >= 1: print(path)
            continue
        if len(raw) == 0:
            failed = True; reasons.append("empty"); ret |= 2
            if not quiet: eprint(f"{path} could not be opened for reading.")
        else:
            fmt = detect_alignment_format(raw)
            if fmt == "BAM":
                # EOF check
                if not raw.endswith(BGZF_EOF):
                    # also accept if final bgzf block is an empty block equal to EOF somewhere at end
                    failed = True; ret |= 1
                    if not quiet: eprint(f"{path} had no EOF block.")
                try:
                    dec, blocks = BGZFBlocks.decompress(raw)
                    h, recs = decode_bam(dec, blocks)
                    if not unmapped_ok and not h.refs:
                        failed = True; ret |= 4
                        if not quiet: eprint(f"{path} had no targets in header.")
                    if not h.lines and not h.refs:
                        failed = True; ret |= 2
                        if not quiet: eprint(f"{path} had an empty header.")
                except Exception:
                    failed = True; ret |= 2
                    if not quiet: eprint(f"{path} could not be opened for reading.")
            elif fmt == "CRAM":
                # Can't decode; assume OK if magic present (except no-target check skipped)
                pass
            else:
                # SAM
                try:
                    data = read_alignments(path)
                    if not unmapped_ok and not data.header.refs:
                        # SAM files with reads to refs need @SQ; headerless SAM accepted by quickcheck? Only fail if header missing entirely?
                        # hts checks requires_targets if any mapped record exists
                        if any((not r.is_unmapped()) for r in data.records):
                            failed = True; ret |= 4
                            if not quiet: eprint(f"{path} had no targets in header.")
                    if not data.records and not data.header.lines:
                        failed = True; ret |= 2
                except Exception:
                    failed = True; ret |= 2
                    if not quiet: eprint(f"{path} could not be opened for reading.")
        if failed and verbose >= 1:
            print(path)
        elif verbose >= 2:
            print(path)
    return ret

def cmd_samples(args):
    spec = [S("help_", short="?", help="-?"), S("header", short="h"), S("indexed", short="i"),
            S("tag", short="T", arg=True), S("output", short="o", arg=True),
            S("fasta", short="f", arg=True, multi=True), S("fasta_list", short="F", arg=True),
            S("customized_index", short="X"),
            S("threads", short="@", long="threads", arg=True),
            S("input_fmt_option", long="input-fmt-option", arg=True, multi=True),
            S("reference", long="reference", arg=True), S("verbosity", long="verbosity", arg=True)]
    vals, pos = OptParser("samples", spec).parse(args)
    tag = vals.get("tag", "SM")
    paths = []
    pairs = []  # (path,index)
    raw_items = []
    if pos:
        raw_items = pos
    else:
        # read from stdin lines (paths, or pairs tab separated when -X)
        for ln in sys.stdin.read().splitlines():
            if ln.strip(): raw_items.append(ln.strip())
    if vals.get("customized_index"):
        if pos:
            # form: files first then indexes if extra count matches? usage f1 f2 idx1 idx2
            # If items come from stdin as tab-pairs, handle separately
            tab_pairs = [x for x in raw_items if "\t" in x]
            if tab_pairs and len(tab_pairs) == len(raw_items):
                for x in raw_items:
                    a, b = x.split("\t", 1); pairs.append((a.strip(), b.strip()))
            else:
                half = len(raw_items) // 2
                if len(raw_items) % 2 == 0 and half > 0:
                    for i in range(half):
                        pairs.append((raw_items[i], raw_items[half + i]))
                else:
                    for x in raw_items: pairs.append((x, None))
        else:
            for x in raw_items:
                if "\t" in x:
                    a, b = x.split("\t", 1); pairs.append((a.strip(), b.strip()))
                else:
                    pairs.append((x, None))
    else:
        for x in raw_items: pairs.append((x, None))
    # fasta collection for 3rd column
    fa_files = list(vals.get("fasta") or [])
    if vals.get("fasta_list"):
        with open(vals["fasta_list"]) as fh:
            fa_files += [l.strip() for l in fh if l.strip()]
    fa_md5 = []  # (path, set of md5 uppercase seqs)
    for fp in fa_files:
        try:
            sset = {hashlib.md5(s.upper().encode()).hexdigest() for n, s, d in read_fasta(fp)}
        except Exception:
            sset = set()
        fa_md5.append((fp, sset))
    out_lines = []
    if vals.get("header"):
        cols = [f"#{tag}", "PATH"]
        if fa_files: cols.append("REF")
        out_lines.append("\t".join(cols))
    for path, idx in pairs:
        if vals.get("indexed"):
            if not has_index(path, idx):
                continue
        try:
            data = load_alignments(path, "samples")
        except Exception:
            continue
        vals_list = []
        for ln in data.header.lines:
            if ln.startswith("@RG"):
                _, tags, _ = parse_header_line(ln)
                v = tags.get(tag)
                if v is not None and v not in vals_list:
                    vals_list.append(v)
        if not vals_list:
            cols = [".", path]
            if fa_files: cols.append(_samples_ref_col(data.header, fa_md5))
            out_lines.append("\t".join(cols))
        else:
            for v in vals_list:
                cols = [v, path]
                if fa_files: cols.append(_samples_ref_col(data.header, fa_md5))
                out_lines.append("\t".join(cols))
    text = "\n".join(out_lines) + ("\n" if out_lines else "")
    _write_out(text, vals.get("output"))
    return 0

def _samples_ref_col(header, fa_md5):
    m5s = []
    for ln in header.lines:
        if ln.startswith("@SQ"):
            _, tags, _ = parse_header_line(ln)
            if "M5" in tags: m5s.append(tags["M5"])
    if not m5s: return "."
    for fp, sset in fa_md5:
        if all(m in sset for m in m5s):
            return fp
    return "."

def cmd_cat(args):
