            S("reference", long="reference", arg=True), S("verbosity", long="verbosity", arg=True)]
    vals, pos = OptParser("samples", spec).parse(args)
    tag = vals.get("tag", "SM")
    paths = []
    pairs = []  # (path,index)
    raw_items = []
    if pos:
        raw_items = pos
    else:
        # read from stdin lines (paths, or pairs tab separated when -X)
        for ln in sys.stdin.read().splitlines():
            if ln.strip(): raw_items.append(ln.strip())
    if vals.get("customized_index"):
        if pos:
            # form: files first then indexes if extra count matches? usage f1 f2 idx1 idx2
            # If items come from stdin as tab-pairs, handle separately
            tab_pairs = [x for x in raw_items if "\t" in x]
            if tab_pairs and len(tab_pairs) == len(raw_items):
                for x in raw_items:
                    a, b = x.split("\t", 1); pairs.append((a.strip(), b.strip()))
            else:
                half = len(raw_items) // 2
                if len(raw_items) % 2 == 0 and half > 0:
                    for i in range(half):
                        pairs.append((raw_items[i], raw_items[half + i]))
                else:
                    for x in raw_items: pairs.append((x, None))
        else:
            for x in raw_items:
                if "\t" in x:
                    a, b = x.split("\t", 1); pairs.append((a.strip(), b.strip()))
                else:
                    pairs.append((x, None))
    else:
        for x in raw_items: pairs.append((x, None))
    # fasta collection for 3rd column
    fa_files = list(vals.get("fasta") or [])
    if vals.get("fasta_list"):
        with open(vals["fasta_list"]) as fh:
            fa_files += [l.strip() for l in fh if l.strip()]
    fa_md5 = []  # (path, set of md5 uppercase seqs)
    for fp in fa_files:
        try:
            sset = {hashlib.md5(s.upper().encode()).hexdigest() for n, s, d in read_fasta(fp)}
        except Exception:
            sset = set()
        fa_md5.append((fp, sset))
    out_lines = []
    if vals.get("header"):
        cols = [f"#{tag}", "PATH"]
        if fa_files: cols.append("REF")
        out_lines.append("\t".join(cols))
    for path, idx in pairs:
        if vals.get("indexed"):
            if not has_index(path, idx):
                continue
        try:
            data = load_alignments(path, "samples")
        except Exception:
            continue
        vals_list = []
        for ln in data.header.lines:
            if ln.startswith("@RG"):
                _, tags, _ = parse_header_line(ln)
                v = tags.get(tag)
                if v is not None and v not in vals_list:
                    vals_list.append(v)
        if not vals_list:
            cols = [".", path]
            if fa_files: cols.append(_samples_ref_col(data.header, fa_md5))
            out_lines.append("\t".join(cols))
        else:
            for v in vals_list:
                cols = [v, path]
                if fa_files: cols.append(_samples_ref_col(data.header, fa_md5))
                out_lines.append("\t".join(cols))
    text = "\n".join(out_lines) + ("\n" if out_lines else "")
    _write_out(text, vals.get("output"))
    return 0

def _samples_ref_col(header, fa_md5):
    m5s = []
    for ln in header.lines:
        if ln.startswith("@SQ"):
            _, tags, _ = parse_header_line(ln)
            if "M5" in tags: m5s.append(tags["M5"])
    if not m5s: return "."
    for fp, sset in fa_md5:
        if all(m in sset for m in m5s):
            return fp
    return "."

def cmd_cat(args):
