        self.adj_qual = qual; self.is_del = False; self.is_refskip = False
        self.is_first = False; self.is_last = False
        self.insertion = []  # list of chars; '*' means padding
        self.deletion = 0
        self.file_idx = 0; self.sample_idx = 0; self.overlapped = False

def record_pileup_entries(rec):
    """Yield (refpos1, PileupEntry) in reference order."""
    if rec.pos <= 0 or rec.rname in ("*", "") or not rec.cigar or rec.seq == "*":
        return
    seq = rec.seq; quals = rec.qual_list()
    q = 0; rpos = rec.pos
    entries = []
    prev = None
    for ln, op in rec.cigar:
        if op in "M=X":
            for _ in range(ln):
                base = seq[q] if q < len(seq) else "N"
                qual = quals[q] if q < len(quals) else 255
                e = PileupEntry(rec, q, base, qual)
                entries.append((rpos, e)); prev = e
                q += 1; rpos += 1
        elif op == "I":
            if prev is not None:
                for _ in range(ln):
                    base = seq[q] if q < len(seq) else "N"
                    prev.insertion.append(base); q += 1
            else:
                q += ln
        elif op == "P":
            if prev is not None:
                # Bob: padding columns in an insertion show as '*'. But a P that is
                # not adjacent to an insertion (between Ms with no I) is also shown
                # as a 1-base insertion by bam_plp.
                for _ in range(ln):
                    prev.insertion.append("*")
        elif op == "D":
            if prev is not None:
                prev.deletion += ln
            for _ in range(ln):
                # qpos points to the next query base
                qual = quals[q] if q < len(quals) else (quals[-1] if quals else 255)
                e = PileupEntry(rec, q, "*", qual); e.is_del = True
                entries.append((rpos, e)); prev = e
                rpos += 1
        elif op == "N":
            for _ in range(ln):
                qual = quals[q] if q < len(quals) else (quals[-1] if quals else 255)
                e = PileupEntry(rec, q, ">", qual); e.is_refskip = True
                entries.append((rpos, e)); prev = e
                rpos += 1
        elif op == "S":
            q += ln
        elif op == "H":
            pass
        elif op == "B":
            q = max(0, q - ln); rpos = max(rec.pos, rpos - ln)
    if entries:
        entries[0][1].is_first = True
        entries[-1][1].is_last = True
    yield from entries

