    """Return OrderedDict ref -> dict pos-> [entries], processing records in
    pileup insertion order (coordinate sorted)."""
    ridx = header.ref_index() if header else {}
    def sk(rec):
        return (ridx.get(rec.rname, 9999), rec.pos if rec.pos > 0 else 0)
    ordered = sorted(list(enumerate(records)), key=lambda x: (sk(x[1]), x[0]))
    pile = OrderedDict()
    for _, rec in ordered:
        for pos, e in record_pileup_entries(rec):
            pile.setdefault(rec.rname, {}).setdefault(pos, []).append(e)
    return pile

