    """Mark overlapped bases from paired templates (mpileup default)."""
    for ref, posmap in pile_by_ref.items():
        for pos, entries in posmap.items():
            # group by qname; only for paired reads with 2 distinct records
            byq = defaultdict(list)
            for e in entries:
                if e.rec.is_paired() and not e.is_del and not e.is_refskip:
                    byq[e.rec.qname].append(e)
            for q, es in byq.items():
                # distinct record objects
                rec_ids = {id(e.rec) for e in es}
                if len(rec_ids) < 2: continue
                if len(es) < 2: continue
                # keep highest adj_qual; tie -> earliest entry
                keep = max(range(len(es)), key=lambda i: (es[i].adj_qual if es[i].adj_qual != 255 else 255, -i))
                for i, e in enumerate(es):
                    if i != keep:
                        e.overlapped = True

