    if rec.rname in ("*", "") or rec.pos <= 0 or not rec.cigar:
        return False
    if req_flags and (rec.flag & req_flags) != req_flags:
        return False
    if excl_flags and (rec.flag & excl_flags):
        return False
    if rec.mapq < min_mq:
        return False
    if min_len and rec.seq_len() < min_len:
        return False
    if not count_orphans and rec.is_paired() and not (rec.flag & 0x2):
        # mpileup-specific checks handled by caller flag use_orphan_filter
        pass
    return True

def get_ref_base(refseq, pos1):
    if refseq is None or pos1 < 1 or pos1 > len(refseq):
        return "N"
    return refseq[pos1 - 1]

