_mp_adj_mapq = {}
def _entry_mapq(e):
    return _mp_adj_mapq.get(id(e.rec), e.rec.mapq)

def _mpileup_sample_text(entries, refbase, refseq, pos, vals, extra_fields, outsep, outempty):
    depth = len(entries)
    if depth == 0:
        cols = ["0", "", ""]
        if vals.get("output_BP") or vals.get("output_BP5"): cols.append("")
        if vals.get("output_MQ"): cols.append("")
        if vals.get("output_QNAME"): cols.append("")
        for _ in extra_fields: cols.append("")
        return cols
    bases = []
    quals = []
    no_ins = vals.get("no_output_ins", 0) or 0; no_del = vals.get("no_output_del", 0) or 0
    for e in entries:
        rev = e.rec.is_reverse()
        qv = 93 if e.adj_qual == 255 else max(0, min(93, e.adj_qual))
        quals.append(chr(qv + 33))
        s = ""
        if e.is_first and not vals.get("no_output_ends"):
            mq = min(_entry_mapq(e), 93)
            s += "^" + chr(mq + 33)
        if e.is_refskip:
            s += "<" if rev else ">"
        elif e.is_del:
            s += "#" if (vals.get("reverse_del") and rev) else "*"
        else:
            b = e.base
            if refbase and refbase.upper() != "N" and (b == "=" or b.upper() == refbase.upper()):
                s += "," if rev else "."
            else:
                if b == "=" and refseq is not None:
                    b = refbase
                s += b.lower() if rev else b.upper()
        # insertion
        if e.insertion:
            ilen = len(e.insertion)
            if no_ins == 0:
                ins_seq_chars = []
                for c in e.insertion:
                    if c == "*": ins_seq_chars.append("*")
                    elif c == "=": ins_seq_chars.append("=")
                    else: ins_seq_chars.append(c.lower() if rev else c.upper())
                s += f"+{ilen}" + "".join(ins_seq_chars)
            elif no_ins == 1:
                s += f"+{ilen}"
            else:
                pass
        # deletion marker attaches to this entry if deletion follows
        if e.deletion:
            dlen = e.deletion
            if no_del == 0:
                dseq = ""
                if refseq is not None:
                    dseq = refseq[pos:pos + dlen]  # pos is 1-based current; next ref base indices: pos (0based)=pos
                    # refseq index for next base after current (pos+1 in 1based) is pos (0based)
                else:
                    dseq = "N" * dlen
                dseq = dseq.lower() if rev else dseq.upper()
                s += f"-{dlen}" + dseq
            elif no_del == 1:
                s += f"-{dlen}"
            else:
                pass
        if e.is_last and not vals.get("no_output_ends"):
            s += "$"
        bases.append(s)
    cols = [str(depth), "".join(bases), "".join(quals)]
    if vals.get("output_BP") or vals.get("output_BP5"):
        vals_bp = []
        for e in entries:
            if vals.get("output_BP5"):
                if e.rec.is_reverse():
                    vals_bp.append(str(e.rec.seq_len() - e.qpos))
                else:
                    vals_bp.append(str(e.qpos + 1))
            else:
                vals_bp.append(str(e.qpos + 1))
        cols.append(outsep.join(vals_bp))
    if vals.get("output_MQ"):
        cols.append("".join(chr(min(_entry_mapq(e), 93) + 33) for e in entries))
    if vals.get("output_QNAME"):
        cols.append(outsep.join(e.rec.qname for e in entries))
    for f in extra_fields:
        vs = []
        for e in entries:
            vs.append(_mpileup_extra_value(e, f, outempty))
        cols.append(outsep.join(vs))
    return cols

def _mpileup_extra_value(e, field, outempty):
    r = e.rec; F = field.upper()
    if F == "FLAG": return str(r.flag)
    if F == "MAPQ": return str(_entry_mapq(e))
    if F in ("QNAME", "READNAME"): return r.qname
    if F == "RNAME": return r.rname
    if F == "POS": return str(r.pos)
    if F == "CIGAR": return cigar_to_str(r.cigar)
    if F in ("RNEXT", "MRNAME"): return r.rname if r.rnext == "=" else r.rnext
    if F in ("PNEXT", "MPOS"): return str(r.pnext)
    if F == "TLEN": return str(r.tlen)
    if F == "SEQ": return r.seq
    if F == "QUAL": return r.qual
    if F in ("QPOS", "BP"): return str(e.qpos + 1)
    if len(field) == 2:
        tg = r.get_tag_typed(field)
        if tg is None: return outempty
        typ, v = tg
        if typ == "B":
            return ",".join(str(x) for x in v[1])
        return str(v)
    # maybe it is a tag name as given case
    tg = r.get_tag_typed(field)
    if tg is None: return outempty
    return str(tg[1])

