class OutputSink:
    def __init__(self, path, compression=1):
        self.path = path; self.compression = compression
        self.is_gz = False; self.fh = None; self.bgzf = None; self.buffer = []
        if path is None or path == "-":
            self.fh = None
        else:
            if path.endswith(".gz") or path.endswith(".bgzf"):
                self.is_gz = True
                self.fh = open(path, "wb"); self.bgzf = BGZFWriter(self.fh, level=compression)
            else:
                self.fh = open(path, "w")
    def write(self, text):
        if self.path is None or self.path == "-":
            sys.stdout.write(text)
        elif self.is_gz:
            self.bgzf.write(text.encode())
        else:
            self.fh.write(text)
    def close(self):
        if self.bgzf: self.bgzf.close()
        if self.fh: 
            try: self.fh.close()
            except Exception: pass

def _parse_index_format(fmt, barcode, qualstr=None):
    """Parse barcode according to index-format. Returns list of (seq,qual) for i tokens."""
    if not fmt or not barcode:
        return []
    tokens = []
    i = 0
    while i < len(fmt):
        kind = fmt[i]; i += 1
        if kind not in "in": continue
        if i < len(fmt) and fmt[i] == "*":
            tokens.append((kind, "*")); i += 1
        else:
            j = i
            while j < len(fmt) and fmt[j].isdigit(): j += 1
            if j == i: tokens.append((kind, 0))
            else: tokens.append((kind, int(fmt[i:j]))); i = j
    seps = "-+"
    out = []
    pos = 0
    for kind, ln in tokens:
        if ln == "*":
            start = pos
            while pos < len(barcode) and barcode[pos] not in seps:
                pos += 1
            seg = barcode[start:pos]
            qseg = (qualstr[start:pos] if qualstr else None)
            if pos < len(barcode): pos += 1  # skip separator (also skip in qualstr index? keep simple)
        else:
            seg = barcode[pos:pos+ln]; qseg = (qualstr[pos:pos+ln] if qualstr else None); pos += ln
        if kind == "i":
            out.append((seg, qseg))
    return out

