class Lrand48:
    def __init__(self, seed):
        self.state = ((seed & 0xffffffff) << 16) | 0x330e
    def next(self):
        self.state = (self.state * 0x5DEECE66D + 0xB) & ((1 << 48) - 1)
        return self.state >> 17

def _replace_header_tag(line, tag, newval):
    f = line.split("\t")
    for i in range(1, len(f)):
        if f[i].startswith(tag + ":"):
            f[i] = f"{tag}:{newval}"; break
    else:
        f.append(f"{tag}:{newval}")
    return "\t".join(f)

