def _unclipped_start(rec):
    # 5' coordinate adjustments using leading/trailing soft (and hard?) clips
    # samtools uses bam_endpos and clipping; softly clipped bases extend alignments.
    lc = 0; rc = 0
    if rec.cigar:
        i = 0
        while i < len(rec.cigar) and rec.cigar[i][1] in ("H", "S"):
            if rec.cigar[i][1] == "S": lc += rec.cigar[i][0]
            i += 1
        i = len(rec.cigar) - 1
        while i >= 0 and rec.cigar[i][1] in ("H", "S"):
            if rec.cigar[i][1] == "S": rc += rec.cigar[i][0]
            i -= 1
    return (rec.pos - lc, rec.end_pos() + rc, lc, rc)

