            is_pair = (not a_rec.is_unmapped() and not b_rec.is_unmapped() and a_rec.rname == b_rec.rname and a_rec.rname not in ("*", ""))
            if is_pair:
                subjects.append({"indices": pair_i, "kind": "pair", "qname": qname, "aux": []})
            else:
                # treat each mapped one as single
                for i in pair_i:
                    if not records[i].is_unmapped():
                        subjects.append({"indices": [i], "kind": "single", "qname": qname, "aux": []})
                    else:
                        subjects.append({"indices": [i], "kind": "unmapped", "qname": qname, "aux": [], "skip": True})
        for i in remaining_primaries:
            if not records[i].is_unmapped():
                subjects.append({"indices": [i], "kind": "single", "qname": qname, "aux": []})
            else:
                subjects.append({"indices": [i], "kind": "unmapped", "qname": qname, "aux": [], "skip": True})
        # link supplementary / secondary to primary with same segment for -S
        # find parent subject containing a primary with same read1/read2 designation
        for ai in secondaries + supps:
            ar = records[ai]
            parent = None
            for subj in subjects:
                if subj["qname"] != qname: continue
                for pi in subj["indices"]:
                    pr = records[pi]
                    if (ar.flag & 0x40 and pr.flag & 0x40) or (ar.flag & 0x80 and pr.flag & 0x80) or (not (ar.flag & 0xc0) and len(subj["indices"]) == 1):
                        parent = subj; break
                if parent: break
            if parent is None and subjects:
                # attach to last subject of this qname
                for subj in reversed(subjects):
                    if subj["qname"] == qname: parent = subj; break
            if parent is not None:
                parent["aux"].append(ai)
