    def barcode_for(rec):
        if vals.get("barcode_tag"):
            v = rec.get_tag(vals["barcode_tag"]); return "" if v is None else str(v)
        if vals.get("barcode_name"):
            parts = rec.qname.split(":")
            return parts[7] if len(parts) > 7 else ""
        if vals.get("barcode_rgx"):
            m = re.search(vals["barcode_rgx"], rec.qname)
            return m.group(1) if m and m.groups() else (m.group(0) if m else "")
