            a, b = recs
            if mode == "s":
                fps = sorted((_five_prime_pos(a), a.is_reverse(), _five_prime_pos(b), b.is_reverse()))
                pair5 = tuple(sorted([(_five_prime_pos(a), "R" if a.is_reverse() else "F"), (_five_prime_pos(b), "R" if b.is_reverse() else "F")]))
                return ("pair", a.rname, pair5, bc, rg)
            else:
                a_us, a_ue, _, _ = _unclipped_start(a); b_us, b_ue, _, _ = _unclipped_start(b)
                tstart = min(a_us, b_us); tend = max(a_ue, b_ue)
