                left, right = (a, b) if a.pos <= b.pos else (b, a)
                orient = ("R" if left.is_reverse() else "F") + ("R" if right.is_reverse() else "F")
                return ("pair", a.rname, tstart, tend, orient, bc, rg)
        else:
            r = recs[0]
            return ("single", r.rname, _five_prime_pos(r), "R" if r.is_reverse() else "F", bc, rg)
