                f"DUPLICATE SINGLE:\t{dup_singles}\n"
                f"DUPLICATE PAIR OPTICAL:\t{0}\n"
                f"DUPLICATE SINGLE OPTICAL:\t{0}\n"
                f"DUPLICATE NONOPTICAL:\t{dup_pairs + dup_singles}\n"
                f"NON DUPLICATE PAIR:\t{total_pairs - dup_pairs}\n"
                f"NON DUPLICATE SINGLE:\t{total_singles - dup_singles}\n"
                f"TOTAL READS:\t{len(records)}\n"
                f"PERCENT DUPLICATION:\t{pct:.2f}\n")
