    efmt, _ = parse_output_fmt(vals.get("output_fmt"))
    v2 = dict(vals); v2["fmt_explicit"] = efmt
    output_alignments(out_path, data.header, out_recs, v2, default_stdout="BAM", compression_level=comp, argv=ORIGINAL_ARGV)
    return 0

