            S("output", short="o", arg=True), S("no_PG", long="no-PG"),
            S("help_long", short="?", help="-?"),
            S("input_fmt_option", long="input-fmt-option", arg=True, multi=True),
            S("output_fmt", long="output-fmt", arg=True), S("output_fmt_option", long="output-fmt-option", arg=True, multi=True),
            S("write_index", long="write-index"), S("verbosity", long="verbosity", arg=True),
            S("threads", short="@", long="threads", arg=True)]
    vals, pos = OptParser("depad", spec).parse(args)
    if not pos:
        usage_noargs("depad")
    in_path = pos[0]
    data = load_alignments(in_path, "depad")
    out_path = vals.get("output")
    # header is written before reference check in reference (observed) - emulate for SAM output
    efmt, _ = parse_output_fmt(vals.get("output_fmt"))
    outfmt = "SAM" if vals.get("sam_out") else (efmt or alignment_format_from_name(out_path, default="BAM"))
    out_header = prepare_output_header(data.header, vals, argv=ORIGINAL_ARGV, add_pg=not vals.get("no_PG"))
    refseqs = {}; embedded = {}
    if not vals.get("reference"):
        eprint("[depad] Warning - reference lengths will not be corrected without FASTA reference")
        # look for embedded reference records
        for r in data.records:
            # Embedded refs in padded SAM are records named same as reference with a long sequence
            ref_len = dict(data.header.refs).get(r.rname, 0)
            if r.qname == r.rname and ref_len and r.seq_len() >= ref_len * 0.9:
                embedded[r.rname] = r.seq
        if not embedded:
            if outfmt == "SAM":
                _write_out(out_header.text(), out_path)
            raise SamtoolsError("[depad] ERROR: Missing ref embedded reference sequence (and no FASTA file)\n", 1)
        refseqs = embedded
    else:
        refseqs = {n: s for n, s, d in read_fasta(vals["reference"])}
    out_recs = []
    for orig in data.records:
        if orig.rname in embedded and orig.qname == orig.rname:
            continue
        r = orig.copy()
        refseq = refseqs.get(r.rname)
        if refseq is None or r.pos <= 0 or not r.cigar:
            out_recs.append(r); continue
        # build map padded pos->unpadded pos (0 if pad '*')
        # Walk cigar against padded reference
        padded = refseq
        unpad_map = []
        cnt = 0
        for ch in padded:
            if ch == "*": unpad_map.append(0)
            else: cnt += 1; unpad_map.append(cnt)
        total_unpad = cnt
        q = 0; rp = r.pos - 1
        new_ops = []
        def add(n, op):
            if n <= 0: return
            if new_ops and new_ops[-1][1] == op: new_ops[-1] = (new_ops[-1][0] + n, op)
            else: new_ops.append((n, op))
        first_ref = None
        for length, op in r.cigar:
            if op in "M=X":
                for _ in range(length):
                    is_pad = (0 <= rp < len(padded) and padded[rp] == "*")
                    if is_pad:
                        add(1, "I")
                    else:
                        add(1, op)
                        if first_ref is None and 0 <= rp < len(unpad_map): first_ref = unpad_map[rp]
                    q += 1; rp += 1
            elif op == "I":
                add(length, "I"); q += length
            elif op == "D":
                for _ in range(length):
                    is_pad = (0 <= rp < len(padded) and padded[rp] == "*")
                    if not is_pad: add(1, "D")
                    rp += 1
            elif op == "N":
                for _ in range(length):
                    is_pad = (0 <= rp < len(padded) and padded[rp] == "*")
                    if not is_pad: add(1, "N")
                    rp += 1
            elif op == "P":
                rp += length
            elif op == "S":
                add(length, "S"); q += length
            elif op == "H":
                add(length, "H")
        # leading insertions before first ref: keep as I; position at next base
        r.cigar = new_ops
        if first_ref: r.pos = first_ref
