    comp = 0 if vals.get("uncompressed_flag") else (1 if vals.get("fast_compress") else 6)
    v2 = dict(vals); v2["fmt_explicit"] = outfmt; v2["no_PG"] = True
    output_alignments(out_path, hdr, out_recs, v2, default_stdout=outfmt, compression_level=comp, add_pg=False, argv=ORIGINAL_ARGV)
    return 0

