def _tview_render(data, refseqs, chrom, start_pos, width, hide_inserts=False, sample=None):
    header = data.header
    refs = dict(header.refs)
    if chrom is None:
        # first ref with a mapped read
        for r in data.records:
            if r.rname in refs and r.pos > 0:
                chrom = r.rname; start_pos = start_pos or 1; break
        if chrom is None and header.refs:
            chrom = header.refs[0][0]
    if start_pos is None or start_pos < 1: start_pos = 1
    # sample filter mapping RG->SM
    rg_sm = {}
    for ln in header.lines:
        if ln.startswith("@RG"):
            _, tg, _ = parse_header_line(ln)
            if "ID" in tg: rg_sm[tg["ID"]] = tg.get("SM")
    def sample_ok(rec):
        if sample is None: return True
        rg = rec.get_tag("RG")
        if rg is None: return False
        return str(rg) == sample or rg_sm.get(str(rg)) == sample
    refseq = refseqs.get(chrom, "") if refseqs else ""
    reflen = refs.get(chrom, len(refseq))
    records = [r for r in data.records if r.rname == chrom and r.pos > 0 and r.cigar and sample_ok(r)
               and record_overlaps_region(r, chrom, start_pos, start_pos + width * 2)]
    pile = build_pileup(records, header).get(chrom, {})
    cols = []  # dicts pos, ins_index (0 main, >0 inserts), refchar
    col_index = {}
    p = start_pos
    while len(cols) < width and p <= reflen:
        refchar = refseq[p-1].upper() if p <= len(refseq) else "N"
        col_index[(p, 0)] = len(cols); cols.append({"pos": p, "ins": 0, "char": refchar})
        if len(cols) >= width: break
        maxins = 0
        if not hide_inserts:
            for e in pile.get(p, []):
                maxins = max(maxins, len(e.insertion))
            for k in range(1, maxins + 1):
                if len(cols) >= width: break
                col_index[(p, k)] = len(cols); cols.append({"pos": p, "ins": k, "char": "*"})
        p += 1
    while len(cols) < width:
        cols.append({"pos": p, "ins": 0, "char": "N"}); p += 1
    # ruler
    ruler = [" "] * width
    for c in cols:
        if c["ins"] == 0 and (c["pos"] % 10 == 1):
            label = str(c["pos"]); at = col_index[(c["pos"], 0)]
            for i, ch in enumerate(label):
                if at + i < width: ruler[at + i] = ch
    ref_line = "".join(c["char"] for c in cols)
    # consensus
    consensus = []
    iup = {frozenset("A"): "A", frozenset("C"): "C", frozenset("G"): "G", frozenset("T"): "T",
           frozenset("AG"): "R", frozenset("CT"): "Y", frozenset("GC"): "S", frozenset("AT"): "W",
           frozenset("GT"): "K", frozenset("AC"): "M", frozenset("CGT"): "B", frozenset("AGT"): "D",
           frozenset("ACT"): "H", frozenset("ACG"): "V", frozenset("ACGT"): "N"}
    for c in cols:
        if c["ins"]:
            consensus.append(" "); continue
        entries = pile.get(c["pos"], [])
        counts = Counter()
        for e in entries:
            if e.is_refskip: continue
            if e.is_del: counts["*"] += 1
            else: counts[c["char"] if e.base == "=" else e.base.upper()] += 1
        total = sum(counts.values())
        if total == 0:
            consensus.append(" "); continue
        cand = [b for b, n in counts.items() if n / total >= 0.2]
        if len(cand) == 1:
            b = cand[0]
            consensus.append("." if b == c["char"] else b)
        else:
            nonstar = [b for b in cand if b != "*"]
            if len(nonstar) == 1 and "*" in cand:
                consensus.append("*" if counts["*"] > counts[nonstar[0]] else ("." if nonstar[0] == c["char"] else nonstar[0]))
            else:
                consensus.append(iup.get(frozenset(nonstar), "N") if nonstar else "*")
    # read spans in columns
    spans = []
    for rec in records:
        chars = {}
        for pos, e in record_pileup_entries(rec):
            key = (pos, 0)
            if key not in col_index: continue
            ci = col_index[key]
            rev = rec.is_reverse()
            refc = refseq[pos-1].upper() if pos <= len(refseq) else "N"
            if e.is_refskip:
                ch = "<" if rev else ">"
            elif e.is_del:
                ch = "*"
            else:
                if e.base == "=" or e.base.upper() == refc:
                    ch = "," if rev else "."
                else:
                    ch = e.base.lower() if rev else e.base.upper()
            chars[ci] = ch
            if not hide_inserts:
                for k, ich in enumerate(e.insertion, start=1):
                    ik = (pos, k)
                    if ik in col_index:
                        chars[col_index[ik]] = "*" if ich == "*" else (ich.lower() if rev else ich.upper())
        if chars:
            spans.append((min(chars.keys()), max(chars.keys()), chars))
    spans.sort(key=lambda x: (x[0], x[1]))
    rows = []
    for lo, hi, chars in spans:
        placed = False
        for row in rows:
            if all(ci not in row for ci in chars):
                row.update(chars); placed = True; break
        if not placed:
            rows.append(dict(chars))
    lines = ["".join(ruler), ref_line, "".join(consensus)]
    for row in rows:
        lines.append("".join(row.get(i, " ") for i in range(width)))
    return "\n".join(lines) + "\n", chrom, start_pos

