# ------------------------------------------------------------- checksum (approx)
def _checksum_serialize_aux(rec, tags):
    out = []
    tagset = set(tags)
    for name, typ, v in rec.tags:
        if name in tagset:
            out.append(format_tag_sam(name, typ, v))
    return "\t".join(out).encode()

def cmd_checksum(args):
    spec = [S("exclude_flags", short="F", long="exclude-flags", arg=True), S("require_flags", short="f", long="require-flags", arg=True),
            S("flag_mask", short="b", long="flag-mask", arg=True), S("no_rev_comp", short="c", long="no-rev-comp"),
            S("tags", short="t", long="tags", arg=True), S("in_order", short="O", long="in-order"),
            S("check_pos", short="P", long="check-pos"), S("check_cigar", short="C", long="check-cigar"),
            S("check_mate", short="M", long="check_mate"), S("sanitize", short="z", long="sanitize", arg=True),
            S("count", short="N", long="count", arg=True), S("output", short="o", long="output", arg=True),
            S("show_qc", short="q", long="show-qc"), S("verbose", short="v", long="verbose", count=True),
            S("all_opts", short="a", long="all"), S("tabs", short="T", long="tabs"),
            S("merge", short="m", long="merge", optarg=True), S("bamseqchksum_fmt", short="B", long="bamseqchksum"),
            S("input_fmt_option", long="input-fmt-option", arg=True, multi=True), S("reference", long="reference", arg=True),
            S("threads", short="@", long="threads", arg=True), S("verbosity", long="verbosity", arg=True)]
    vals, pos = OptParser("checksum", spec).parse(args)
    if vals.get("all_opts"):
        vals["check_pos"] = True; vals["check_cigar"] = True; vals["check_mate"] = True; vals["in_order"] = True; vals["no_rev_comp"] = True
        vals["flag_mask"] = "0xfff"; vals["require_flags"] = "0"; vals["exclude_flags"] = "0"
    if vals.get("merge") is not None:
        return _checksum_merge(vals, pos)
    if not pos:
        # stdin empty / no file: captured error
        raise SamtoolsError("[checksum] Failed to process data\n", 1)
    excl = parse_flag_value(vals["exclude_flags"]) if vals.get("exclude_flags") not in (None, "") else 0x900
    reqf = parse_flag_value(vals["require_flags"]) if vals.get("require_flags") not in (None, "") else 0
    fmask = parse_flag_value(vals["flag_mask"]) if vals.get("flag_mask") not in (None, "") else 0xc1
    tag_list = [x.strip() for x in str(vals.get("tags", "BC,FI,QT,RT,TC")).split(",") if x.strip()]
    maxn = int(vals["count"]) if vals.get("count") else 0
    # Gather all files into one report per file (reference prints one block per file)
    blocks = []
    for path in pos:
        data = load_alignments(path, "checksum")
        rg_sm = {}
        for ln in data.header.lines:
            if ln.startswith("@RG"):
                _, tg, _ = parse_header_line(ln)
                if "ID" in tg: rg_sm[tg["ID"]] = tg.get("SM", tg["ID"])
        # group key: sample from RG, '-' if none. QC key all/pass/fail
        groups = OrderedDict()
        def newacc(): return {"count": 0, "flagseq": 0, "name": 0, "qual": 0, "aux": 0, "combined": 0}
        total = 0
        for r in data.records:
            if maxn and total >= maxn: break
            if excl and (r.flag & excl): continue
            if reqf and (r.flag & reqf) != reqf: continue
            total += 1
            seq = r.seq if r.seq != "*" else ""
            qual_raw = bytes(r.qual_list())
            if r.is_reverse() and not vals.get("no_rev_comp"):
                seq_norm = revcomp(seq); qual_norm = qual_raw[::-1]
            else:
                seq_norm = seq; qual_norm = qual_raw
            flags_v = r.flag & fmask
            flag_b = struct.pack("<H", flags_v)
            seq_b = seq_norm.encode()
            name_b = re.sub(r"/[12]$", "", r.qname).encode()
            aux_b = _checksum_serialize_aux(r, tag_list)
            extra = b""
            if vals.get("check_pos"): extra += f"|{r.rname}|{r.pos}".encode()
            if vals.get("check_cigar"): extra += f"|{r.mapq}|{cigar_to_str(r.cigar)}".encode()
            if vals.get("check_mate"): extra += f"|{r.rnext}|{r.pnext}|{r.tlen}".encode()
            payloads = {
                "flagseq": flag_b + seq_b + extra,
                "name": flag_b + seq_b + name_b + extra,
                "qual": flag_b + seq_b + name_b + qual_norm + extra,
                "aux": flag_b + seq_b + aux_b + extra,
                "combined": flag_b + seq_b + name_b + qual_norm + aux_b + extra,
            }
            group = "-"
            rg = r.get_tag("RG")
            if rg is not None: group = rg_sm.get(str(rg), str(rg))
            qc_keys = ["all"]
            if vals.get("show_qc"):
                qc_keys.append("fail" if r.is_qcfail() else "pass")
            keys = [("all", "all"), (group, "all")]
            if vals.get("show_qc"):
                keys.append(("all", qc_keys[-1])); keys.append((group, qc_keys[-1]))
            # de-duplicate when group=="all" etc
            seen_keys = []
            for k in keys:
                if k not in seen_keys: seen_keys.append(k)
            for key in seen_keys:
                acc = groups.setdefault(key, newacc())
                acc["count"] += 1
                for comp, payload in payloads.items():
                    v = zlib.crc32(payload) & 0xffffffff
                    if vals.get("in_order"):
                        acc[comp] = zlib.crc32(payload, acc[comp]) & 0xffffffff
                    else:
                        acc[comp] = (acc[comp] + v) & 0xffffffff
        flag_names = ",".join(n for v, n, _ in FLAG_DEFS if fmask & v) or "-"
        lines = []
        if vals.get("bamseqchksum_fmt"):
            lines.append(f"# bamseqchksum for file: {path}")
        else:
            lines.append(f"# Checksum 1.0 for file: {path}")
        lines.append(f"# Aux tags:          {','.join(tag_list)}")
        lines.append(f"# BAM flags:         {flag_names}")
        lines.append("")
        if vals.get("tabs"):
